        let old = hook_recovery_notice(&app.screen_draw_recovery_bridge)
            .take_screen_draw_recovery(&app.screen_draw_recovery_bridge)
            .unwrap();
        let moved = crate::launcher_parking::LauncherWindowRect {
            left: 600,
            top: 320,
            right: 1050,
            bottom: 610,
        };
