    fn root_result_hint(app: &LauncherApp, index: usize) -> String {
        let target = crate::gui::jump_mode::TargetId::root_result(
            crate::gui::jump_mode::TargetGeneration(app.root_list_geometry.result_generation()),
            index,
        );
        app.jump_mode_ui
            .active_session()
            .expect("Jump Mode session is active")
            .hint_map()
            .hint_for(&target)
            .expect("the requested visible action has a hint")
            .as_str()
            .to_owned()
    }

    fn dialog_hint_for_label(app: &LauncherApp, label: &str) -> String {
        app.jump_mode_ui
            .active_session()
            .expect("Jump Mode session is active")
            .hint_map()
            .assignments()
            .iter()
            .find(|assignment| assignment.target().label() == label)
            .unwrap_or_else(|| {
                panic!(
                    "no active dialog target labeled {label:?}; targets={:?}",
                    app.jump_mode_ui
                        .retained_registry()
                        .targets()
                        .iter()
                        .map(|target| target.metadata().label())
                        .collect::<Vec<_>>()
                )
            })
            .hint()
            .as_str()
            .to_owned()
    }

