    #[test]
    fn jump_mode_snippets_authoring_duplicate_rows_select_without_preview_then_fresh_edit_exact_row()
     {
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let snippets_path = _workspace
            .root()
            .join(crate::plugins::snippets::SNIPPETS_FILE)
            .to_string_lossy()
            .into_owned();
        let entries = vec![
            snippet_fixture_entry("repeated alias", "first body", false, false, vec![], &[]),
            snippet_fixture_entry("repeated alias", "second body", false, false, vec![], &[]),
        ];
        crate::plugins::snippets::save_snippets(&snippets_path, &entries)
            .expect("the duplicate alias fixture is writable");
        prepare_actual_snippet_dialog(&ctx, &mut app, &snippets_path);
        start_actual_snippet_jump_mode(&ctx, &mut app);

        let row_targets = snippet_target_ids(&app, "Snippet entry");
        assert_eq!(row_targets.len(), 2);
        assert_ne!(row_targets[0], row_targets[1]);
        for target in &row_targets {
            assert!(!format!("{target:?}").contains("repeated alias"));
        }
        let second_row = row_targets
            .iter()
            .find(|target| {
                matches!(
                    target.semantic(),
                    crate::gui::jump_mode::SemanticTargetId::Named(identity)
                        if identity.contains("entry/1/preview")
                )
            })
            .expect("the second underlying entry has its own opaque row identity")
            .clone();
        let saved_before = crate::plugins::snippets::load_snippets(&snippets_path).unwrap();
        let row_hint = snippet_hint_for_target(&app, &second_row);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(row_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(app.snippet_dialog.test_selected_entry_index(), Some(1));
        assert!(!app.snippet_dialog.test_is_editing());
        assert!(!app.snippet_prompt_dialog.is_open());

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(!app.snippet_dialog.test_is_editing());
        assert!(!app.snippet_prompt_dialog.is_open());

        let edit_target = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| {
                target.metadata().label() == "Edit snippet"
                    && matches!(
                        target.id().semantic(),
                        crate::gui::jump_mode::SemanticTargetId::Named(identity)
                            if identity.contains("entry/1/edit")
                    )
            })
            .expect("the second row has a separately addressable Edit button")
            .id()
            .clone();
        start_actual_snippet_jump_mode(&ctx, &mut app);
        let edit_hint = snippet_hint_for_target(&app, &edit_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(edit_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(!app.snippet_dialog.test_is_editing());
        assert!(!app.snippet_prompt_dialog.is_open());
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert!(app.snippet_dialog.test_is_editing());
        assert_eq!(app.snippet_dialog.test_edit_index(), Some(1));
        assert_eq!(app.snippet_dialog.test_alias(), "repeated alias");
        assert_eq!(app.snippet_dialog.test_text(), "second body");
        assert_eq!(
            crate::plugins::snippets::load_snippets(&snippets_path).unwrap(),
            saved_before,
            "Select and explicit Edit do not save or start a preview"
        );
        assert!(!app.snippet_prompt_dialog.is_open());
    }

    #[test]
    fn jump_mode_clipboard_browse_hint_selects_duplicate_without_exposing_contents_or_actions() {
        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let private_entry = "private clipboard secret λ\nline two";
        prepare_actual_clipboard_history_dialog(&ctx, &mut app, &[private_entry, private_entry]);
        let original_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();

        let row_targets = clipboard_target_ids(&app, "Clipboard entry");
        assert_eq!(row_targets.len(), 2);
        assert_ne!(row_targets[0], row_targets[1]);
        let dialog_targets = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| {
                target.id().surface()
                    == &crate::gui::jump_mode::SurfaceId::dialog(
                        "clipboard-history",
                        app.jump_mode_ui
                            .dialog_instance(
                                crate::gui::jump_mode::ui::NavigationDialogKind::ClipboardHistory,
                            )
                            .unwrap(),
                    )
            })
            .collect::<Vec<_>>();
        for target in &dialog_targets {
            assert!(!target.metadata().label().contains(private_entry));
            let crate::gui::jump_mode::SemanticTargetId::Named(identity) = target.id().semantic()
            else {
                panic!("clipboard row identities use opaque named tokens");
            };
            assert!(!identity.contains("private clipboard"));
            assert!(!identity.contains("line two"));
        }
        assert_eq!(clipboard_target_ids(&app, "Edit clipboard entry").len(), 2);
        assert_eq!(
            clipboard_target_ids(&app, "Remove clipboard entry").len(),
            2
        );
        assert_eq!(
            clipboard_target_ids(&app, "Close Clipboard History").len(),
            1
        );
        let copy_targets = clipboard_target_ids(&app, "Copy clipboard entry");
        assert_eq!(copy_targets.len(), 2);
        assert_ne!(copy_targets[0], copy_targets[1]);
        for copy_target_id in &copy_targets {
            let target = dialog_targets
                .iter()
                .find(|target| target.id() == copy_target_id)
                .expect("each visible Copy control has a registered target");
            assert_eq!(
                target.metadata().kind(),
                crate::gui::jump_mode::TargetKind::Button
            );
            let crate::gui::jump_mode::SemanticTargetId::Named(identity) = target.id().semantic()
            else {
                panic!("clipboard Copy identities use opaque named tokens");
            };
            assert!(!identity.contains(private_entry));
            assert!(!identity.contains("private clipboard"));
            assert!(!identity.contains("line two"));
        }

        let second_row = row_targets[1].clone();
        let response_id = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.id() == &second_row)
            .unwrap()
            .response_id();
        start_actual_root_jump_mode(&ctx, &mut app);
        let hint = clipboard_hint_for_target(&app, &second_row);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();

        assert_eq!(app.clipboard_dialog.test_selected_entry_index(), Some(1));
        assert!(!app.clipboard_dialog.test_is_editing());
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(response_id));
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes
        );
    }

    #[test]
    fn jump_mode_clipboard_browse_clips_rows_and_keeps_native_selection_when_disabled() {
        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let entries = (0..40)
            .map(|index| format!("private clipboard row {index} with a long preview"))
            .collect::<Vec<_>>();
        let entry_refs = entries.iter().map(String::as_str).collect::<Vec<_>>();
        prepare_actual_clipboard_history_dialog(&ctx, &mut app, &entry_refs);
        let original_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();

        let registered_rows = clipboard_target_ids(&app, "Clipboard entry");
        assert!(!registered_rows.is_empty());
        assert!(registered_rows.len() < entries.len());
        let layer = crate::gui::jump_mode::ui::NavigationDialogKind::ClipboardHistory
            .layer_id()
            .expect("Clipboard History uses a native Middle layer");
        for target_id in &registered_rows {
            let target = app
                .jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .find(|target| target.id() == target_id)
                .unwrap();
            assert!(target.clipped_rect().is_positive());
            assert_eq!(target.layer_id(), layer);
            assert_eq!(ctx.layer_id_at(target.clipped_rect().center()), Some(layer));
        }

        app.set_jump_mode_enabled(false);
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert!(app.jump_mode_ui.retained_registry().targets().is_empty());
        let (first_token, first_response_id, first_visible_rect) = *app
            .clipboard_dialog
            .test_visible_entry_rows()
            .first()
            .expect("a real visible clipboard response remains with Jump Mode disabled");
        assert_eq!(ctx.layer_id_at(first_visible_rect.center()), Some(layer));
        assert!(
            ctx.read_response(first_response_id)
                .is_some_and(|response| response.enabled())
        );

        for pressed in [true, false] {
            let mut events = if pressed {
                vec![egui::Event::PointerMoved(first_visible_rect.center())]
            } else {
                Vec::new()
            };
            events.push(egui::Event::PointerButton {
                pos: first_visible_rect.center(),
                button: egui::PointerButton::Primary,
                pressed,
                modifiers: egui::Modifiers::default(),
            });
            app.run_root_frame_for_test(
                &ctx,
                egui::RawInput {
                    events,
                    ..actual_query_input(true)
                },
                false,
            )
            .0
            .drop_without_applying_deltas();
        }
        assert_eq!(app.clipboard_dialog.test_selected_entry_index(), Some(0));
        assert_eq!(
            app.clipboard_dialog.test_visible_entry_rows()[0].0,
            first_token
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes
        );
    }

    #[test]
    fn jump_mode_clipboard_actions_copy_and_edit_save_cancel_require_fresh_keys() {
        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let private_entry = "clipboard secret λ\nsecond line";
        prepare_actual_clipboard_history_dialog(&ctx, &mut app, &[private_entry]);
        let original_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();
        let fake_clipboard =
            Arc::new(crate::clipboard_modify::clipboard::fake::FakeClipboardBackend::default());
        app.clipboard_dialog
            .set_test_clipboard_backend(fake_clipboard.clone());

        let (copy_target, copy_response) =
            clipboard_target_with_response(&app, "Copy clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &copy_target, copy_response);
        assert!(fake_clipboard.writes().is_empty());
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "hint completion only focuses Copy"
        );
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert_eq!(fake_clipboard.writes(), [private_entry]);
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "Copy does not mutate clipboard history"
        );

        let (edit_target, edit_response) =
            clipboard_target_with_response(&app, "Edit clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &edit_target, edit_response);
        assert!(!app.clipboard_dialog.test_is_editing());
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(app.clipboard_dialog.test_is_editing());
        run_clipboard_frame(&ctx, &mut app, Vec::new());

        let (text_target, text_response) = clipboard_target_with_response(&app, "Clipboard text");
        let edit_widget_id = app
            .clipboard_dialog
            .test_edit_text_widget_id()
            .expect("edit has a session-specific native TextEdit ID");
        assert_eq!(edit_widget_id, text_response);
        complete_clipboard_hint(&ctx, &mut app, &text_target, text_response);
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(text_response));
        let mut text_state = egui::text_edit::TextEditState::load(&ctx, text_response)
            .expect("the focused clipboard editor has native text state");
        text_state
            .cursor
            .set_char_range(Some(egui::text::CCursorRange::two(
                egui::text::CCursor::new(0),
                egui::text::CCursor::new(private_entry.chars().count()),
            )));
        text_state.store(&ctx, text_response);
        run_clipboard_frame(
            &ctx,
            &mut app,
            vec![egui::Event::Text("saved Unicode λ\nsecond line".into())],
        );
        assert_eq!(
            app.clipboard_dialog.test_text(),
            "saved Unicode λ\nsecond line"
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "typing changes only the draft"
        );

        let (save_target, save_response) =
            clipboard_target_with_response(&app, "Save clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &save_target, save_response);
        assert!(app.clipboard_dialog.test_is_editing());
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "hint completion only focuses Save"
        );
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(!app.clipboard_dialog.test_is_editing());
        let saved =
            crate::plugins::clipboard::load_history(crate::plugins::clipboard::CLIPBOARD_FILE)
                .unwrap();
        assert_eq!(saved, ["saved Unicode λ\nsecond line"]);
        let saved_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();

        run_clipboard_frame(&ctx, &mut app, Vec::new());
        let (edit_target, edit_response) =
            clipboard_target_with_response(&app, "Edit clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &edit_target, edit_response);
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(app.clipboard_dialog.test_is_editing());
        run_clipboard_frame(&ctx, &mut app, Vec::new());
        let (cancel_target, cancel_response) =
            clipboard_target_with_response(&app, "Cancel clipboard edit");
        complete_clipboard_hint(&ctx, &mut app, &cancel_target, cancel_response);
        assert!(app.clipboard_dialog.test_is_editing());
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(!app.clipboard_dialog.test_is_editing());
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            saved_bytes,
            "Cancel discards the draft without changing saved history"
        );
    }

    #[test]
    fn jump_mode_clipboard_actions_removal_has_an_exclusive_fresh_confirmation() {
        use crate::gui::jump_mode::ui::{NavigationDialogKind, NavigationOwner};

        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_clipboard_history_dialog(
            &ctx,
            &mut app,
            &["private row to remove", "unrelated row"],
        );
        let original_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();

        let (remove_target, remove_response) =
            clipboard_target_with_response(&app, "Remove clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &remove_target, remove_response);
        assert!(
            app.clipboard_dialog
                .jump_mode_pending_removal_identity()
                .is_none()
        );
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(
            app.clipboard_dialog
                .jump_mode_pending_removal_identity()
                .is_some()
        );
        for _ in 0..2 {
            run_clipboard_frame(&ctx, &mut app, Vec::new());
        }

        let parent_instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::ClipboardHistory)
            .expect("the current history window has a live instance");
        let (confirmation_instance, _) = app
            .clipboard_dialog
            .jump_mode_pending_removal_identity()
            .expect("Remove opens a pending child confirmation");
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::ClipboardRemoval {
                parent_instance,
                confirmation_instance,
            }
        );
        assert!(clipboard_target_ids(&app, "Clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Copy clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Edit clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Remove clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Close Clipboard History").is_empty());
        assert_eq!(
            clipboard_target_ids(&app, "Confirm clipboard entry removal").len(),
            1
        );
        assert_eq!(
            clipboard_target_ids(&app, "Cancel clipboard entry removal").len(),
            1
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes
        );

        let (confirm_target, confirm_response) =
            clipboard_target_with_response(&app, "Confirm clipboard entry removal");
        start_actual_root_jump_mode(&ctx, &mut app);
        let confirm_hint = clipboard_hint_for_target(&app, &confirm_target);
        run_clipboard_frame(
            &ctx,
            &mut app,
            vec![
                egui::Event::Text(confirm_hint),
                key_press(egui::Key::Enter, egui::Modifiers::NONE),
            ],
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(confirm_response)
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "hint completion and same-frame Enter only focus Confirm"
        );
        run_clipboard_frame(
            &ctx,
            &mut app,
            vec![egui::Event::Key {
                key: egui::Key::Enter,
                physical_key: None,
                pressed: true,
                repeat: true,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            original_bytes,
            "held Enter does not cross the confirmation handoff"
        );
        run_clipboard_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert_eq!(
            crate::plugins::clipboard::load_history(crate::plugins::clipboard::CLIPBOARD_FILE,)
                .unwrap(),
            ["unrelated row"],
            "only the later distinct Enter removes the captured row"
        );
    }

    #[test]
    fn jump_mode_clipboard_lifecycle_close_reopen_rejects_old_target() {
        use crate::gui::jump_mode::ui::NavigationDialogKind;

        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_clipboard_history_dialog(&ctx, &mut app, &["reopened row"]);

        let old_instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::ClipboardHistory)
            .expect("the initial Clipboard History window has an observed instance");
        let old_row = clipboard_target_ids(&app, "Clipboard entry")[0].clone();
        start_actual_root_jump_mode(&ctx, &mut app);
        let old_row_hint = clipboard_hint_for_target(&app, &old_row);
        assert!(!old_row_hint.is_empty());
        let (close_target, close_response) =
            clipboard_target_with_response(&app, "Close Clipboard History");
        let close_hint = clipboard_hint_for_target(&app, &close_target);
        run_clipboard_frame(&ctx, &mut app, vec![egui::Event::Text(close_hint)]);
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(close_response));
        assert!(app.clipboard_dialog.open);
        press_and_release_clipboard_enter(&ctx, &mut app);

        assert!(!app.clipboard_dialog.open);
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(clipboard_target_ids(&app, "Clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Edit clipboard entry").is_empty());
        assert!(clipboard_target_ids(&app, "Close Clipboard History").is_empty());

        app.clipboard_dialog.open();
        // One event-free collection pass observes the reopened native window and
        // builds its current target registry before any new hint is accepted.
        run_clipboard_frame(&ctx, &mut app, Vec::new());
        let new_instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::ClipboardHistory)
            .expect("the reopened Clipboard History window has an observed instance");
        assert_ne!(new_instance, old_instance);
        // Ownership changes are observed at the end of that frame, so collect
        // the first registry belonging to the reopened instance next.
        run_clipboard_frame(&ctx, &mut app, Vec::new());
        let new_row = clipboard_target_ids(&app, "Clipboard entry")[0].clone();
        assert_ne!(new_row, old_row, "reopen renews the target identity");
        assert!(app.jump_mode_ui.active_session().is_none());
        run_clipboard_frame(&ctx, &mut app, vec![egui::Event::Text(old_row_hint)]);
        assert!(!app.clipboard_dialog.test_is_editing());
        assert_eq!(app.clipboard_dialog.test_selected_entry_index(), None);
        let (new_edit, new_edit_response) =
            clipboard_target_with_response(&app, "Edit clipboard entry");

        start_actual_root_jump_mode(&ctx, &mut app);
        let session = app
            .jump_mode_ui
            .active_session()
            .expect("the reopened window accepts a fresh hint session");
        assert!(
            session.hint_map().hint_for(&old_row).is_none(),
            "the previous instance's row identity is not in the new hint map"
        );
        assert!(session.hint_map().hint_for(&new_row).is_some());
        let edit_hint = clipboard_hint_for_target(&app, &new_edit);
        run_clipboard_frame(&ctx, &mut app, vec![egui::Event::Text(edit_hint)]);
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(new_edit_response)
        );
        assert!(!app.clipboard_dialog.test_is_editing());
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(app.clipboard_dialog.test_is_editing());
        assert_eq!(app.clipboard_dialog.test_text(), "reopened row");
    }

    #[test]
    fn jump_mode_clipboard_privacy_foreign_window_preserves_draft_and_returns_focus() {
        use crate::gui::jump_mode::ui::{NavigationDialogKind, visible_top_middle_layer};

        let _lock = crate::gui::TEST_MUTEX.lock().unwrap();
        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_clipboard_history_dialog(&ctx, &mut app, &["private saved entry"]);
        let saved_bytes = std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap();

        let (edit_target, edit_response) =
            clipboard_target_with_response(&app, "Edit clipboard entry");
        complete_clipboard_hint(&ctx, &mut app, &edit_target, edit_response);
        press_and_release_clipboard_enter(&ctx, &mut app);
        assert!(app.clipboard_dialog.test_is_editing());
        run_clipboard_frame(&ctx, &mut app, Vec::new());

        let (text_target, text_response) = clipboard_target_with_response(&app, "Clipboard text");
        complete_clipboard_hint(&ctx, &mut app, &text_target, text_response);
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(text_response));
        let mut text_state = egui::text_edit::TextEditState::load(&ctx, text_response)
            .expect("the actual Clipboard TextEdit has native state");
        text_state
            .cursor
            .set_char_range(Some(egui::text::CCursorRange::one(
                egui::text::CCursor::new(app.clipboard_dialog.test_text().chars().count()),
            )));
        text_state.store(&ctx, text_response);
        run_clipboard_frame(&ctx, &mut app, vec![egui::Event::Text(" draft λ".into())]);
        let draft = app.clipboard_dialog.test_text().to_owned();
        assert_eq!(draft, "private saved entry draft λ");
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            saved_bytes,
            "typing remains an unsaved private draft"
        );

        let clipboard_layer = NavigationDialogKind::ClipboardHistory
            .layer_id()
            .expect("Clipboard History has a real Middle layer");
        run_with_secondary_test_window(&ctx, &mut app, actual_query_input(true))
            .drop_without_applying_deltas();
        assert_ne!(visible_top_middle_layer(&ctx), Some(clipboard_layer));
        assert!(!app.clipboard_history_native_ui_owner_current(&ctx, true));
        run_with_secondary_test_window(
            &ctx,
            &mut app,
            egui::RawInput {
                events: vec![egui::Event::Text(" blocked".into())],
                ..actual_query_input(true)
            },
        )
        .drop_without_applying_deltas();
        assert_eq!(app.clipboard_dialog.test_text(), draft);
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            saved_bytes,
            "a foreign foreground window cannot edit or persist the draft"
        );
        assert!(clipboard_target_ids(&app, "Clipboard text").is_empty());

        run_clipboard_frame(&ctx, &mut app, Vec::new());
        assert_eq!(visible_top_middle_layer(&ctx), Some(clipboard_layer));
        assert!(app.clipboard_history_native_ui_owner_current(&ctx, true));
        // The first frame removes the foreign layer; this next event-free
        // pass collects the Clipboard response registry under its restored ownership.
        run_clipboard_frame(&ctx, &mut app, Vec::new());
        let (returned_text_target, returned_text_response) =
            clipboard_target_with_response(&app, "Clipboard text");
        complete_clipboard_hint(
            &ctx,
            &mut app,
            &returned_text_target,
            returned_text_response,
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(returned_text_response),
            "after the foreground window closes, a fresh hint can focus the real editor"
        );
        run_clipboard_frame(&ctx, &mut app, vec![egui::Event::Text(" returned".into())]);
        assert_eq!(
            app.clipboard_dialog.test_text(),
            "private saved entry draft λ returned"
        );
        assert_eq!(
            std::fs::read(crate::plugins::clipboard::CLIPBOARD_FILE).unwrap(),
            saved_bytes
        );
    }

