    #[test]
    fn jump_mode_snippets_authoring_filter_and_reload_replace_old_targets() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let snippets_path = workspace
            .root()
            .join(crate::plugins::snippets::SNIPPETS_FILE)
            .to_string_lossy()
            .into_owned();
        crate::plugins::snippets::save_snippets(
            &snippets_path,
            &[
                snippet_fixture_entry("first alias", "body one", false, false, vec![], &[]),
                snippet_fixture_entry("second alias", "body two", false, false, vec![], &[]),
            ],
        )
        .expect("the Snippets fixture is writable");
        prepare_actual_snippet_dialog(&ctx, &mut app, &snippets_path);
        start_actual_snippet_jump_mode(&ctx, &mut app);
        let old_first = snippet_target_ids(&app, "Snippet entry")
            .into_iter()
            .find(|target| {
                matches!(
                    target.semantic(),
                    crate::gui::jump_mode::SemanticTargetId::Named(identity)
                        if identity.contains("entry/0/preview")
                )
            })
            .expect("the first row is initially visible");
        let old_generation = old_first.generation();

        let filter_target = snippet_target_ids(&app, "Filter snippets")
            .into_iter()
            .next()
            .expect("the list filter is a registered text target");
        let filter_hint = snippet_hint_for_target(&app, &filter_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(filter_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text("second".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert!(
            !app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .any(|target| target.id() == &old_first)
        );
        let filtered_rows = snippet_target_ids(&app, "Snippet entry");
        assert_eq!(filtered_rows.len(), 1);
        assert_ne!(filtered_rows[0], old_first);
        assert_eq!(filtered_rows[0].generation(), old_generation);

        crate::plugins::snippets::save_snippets(
            &snippets_path,
            &[snippet_fixture_entry(
                "replacement",
                "new body",
                false,
                false,
                vec![],
                &[],
            )],
        )
        .expect("the replacement snapshot is writable");
        app.snippet_dialog.test_open_from(&snippets_path);
        for _ in 0..3 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        let replacement_rows = snippet_target_ids(&app, "Snippet entry");
        assert_eq!(replacement_rows.len(), 1);
        assert_ne!(replacement_rows[0], old_first);
        assert_ne!(replacement_rows[0].generation(), old_generation);
    }

    #[test]
    fn jump_mode_snippets_authoring_hidden_fields_stay_private_and_revealed_body_keeps_focus_until_cancel()
     {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let snippets_path = workspace
            .root()
            .join(crate::plugins::snippets::SNIPPETS_FILE)
            .to_string_lossy()
            .into_owned();
        let private_text = "Stored body {{private_key}}";
        let private_default = "PRIVATE_DEFAULT_MARKER";
        let private_tag = "private_tag_marker";
        let entry = snippet_fixture_entry(
            "private alias",
            private_text,
            true,
            true,
            vec![crate::plugins::snippets::SnippetFieldDefinition {
                name: "private_key".into(),
                label: "Private label marker".into(),
                default_value: private_default.into(),
                required: false,
                input_kind: crate::plugins::snippets::SnippetInputKind::Multiline,
            }],
            &[private_tag],
        );
        crate::plugins::snippets::save_snippets(&snippets_path, std::slice::from_ref(&entry))
            .expect("the private-data fixture is writable");
        prepare_actual_snippet_dialog(&ctx, &mut app, &snippets_path);
        start_actual_snippet_jump_mode(&ctx, &mut app);
        let edit_target = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| {
                target.metadata().label() == "Edit snippet"
                    && matches!(
                        target.id().semantic(),
                        crate::gui::jump_mode::SemanticTargetId::Named(identity)
                            if identity.contains("entry/0/edit")
                    )
            })
            .expect("the entry exposes an explicit Edit action")
            .id()
            .clone();
        click_snippet_target(&ctx, &mut app, &edit_target);
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();

        let hidden_labels: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .map(|target| target.metadata().label())
            .collect();
        assert!(hidden_labels.contains(&"Reveal snippet contents"));
        assert!(!hidden_labels.contains(&"Snippet text"));
        assert!(!hidden_labels.contains(&"Prompt field label"));
        assert!(!hidden_labels.contains(&"Prompt field default"));
        for target in app.jump_mode_ui.retained_registry().targets() {
            let metadata = format!("{} {:?}", target.metadata().label(), target.id());
            for secret in [
                private_text,
                private_default,
                private_tag,
                "private_key",
                "Private label marker",
            ] {
                assert!(
                    !metadata.contains(secret),
                    "target metadata leaked {secret:?}"
                );
            }
        }

        let reveal_target = snippet_target_ids(&app, "Reveal snippet contents")
            .into_iter()
            .next()
            .expect("the actual reveal button is registered");
        click_snippet_target(&ctx, &mut app, &reveal_target);
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        let body_targets = snippet_target_ids(&app, "Snippet text");
        assert!(
            !body_targets.is_empty(),
            "body target absent after reveal (editing={}, body_revealed={}, labels={:?})",
            app.snippet_dialog.test_is_editing(),
            app.snippet_dialog.test_body_revealed(),
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .map(|target| target.metadata().label())
                .collect::<Vec<_>>(),
        );
        set_snippet_contents_scroll_offset(&ctx, &mut app, 10_000.0);
        assert_eq!(snippet_target_ids(&app, "Prompt field label").len(), 1);
        assert_eq!(snippet_target_ids(&app, "Prompt field default").len(), 1);
        for target in app.jump_mode_ui.retained_registry().targets() {
            let metadata = format!("{} {:?}", target.metadata().label(), target.id());
            for secret in [
                private_text,
                private_default,
                private_tag,
                "private_key",
                "Private label marker",
            ] {
                assert!(
                    !metadata.contains(secret),
                    "target metadata leaked {secret:?}"
                );
            }
        }

        set_snippet_contents_scroll_offset(&ctx, &mut app, 0.0);
        let body_target = snippet_target_ids(&app, "Snippet text")
            .into_iter()
            .next()
            .expect("the body response is visible after scrolling back to it");
        start_actual_snippet_jump_mode(&ctx, &mut app);
        let body_hint = snippet_hint_for_target(&app, &body_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(body_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        let body_focus = ctx
            .memory(|memory| memory.focused())
            .expect("body editor receives focus");
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(" ✨ line\n猫".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.snippet_dialog.test_text().contains("✨ line\n猫"));
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(body_focus));
        assert_eq!(
            app.snippet_dialog.test_body_editor_widget_id(),
            Some(body_focus)
        );

        set_snippet_contents_scroll_offset(&ctx, &mut app, 10_000.0);
        let cancel_target = snippet_target_ids(&app, "Cancel snippet edit")
            .into_iter()
            .next()
            .expect("Cancel stays available after editing the body");
        click_snippet_target(&ctx, &mut app, &cancel_target);
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert!(!app.snippet_dialog.test_is_editing());
        assert_eq!(
            crate::plugins::snippets::load_snippets(&snippets_path).unwrap(),
            [entry],
            "typing and Cancel leave the saved snapshot untouched"
        );
        assert!(!app.snippet_prompt_dialog.is_open());
    }

    #[test]
    fn jump_mode_snippets_privacy_pending_removal_and_prompt_have_exact_owners() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        let snippets_path = workspace
            .root()
            .join(crate::plugins::snippets::SNIPPETS_FILE)
            .to_string_lossy()
            .into_owned();
        let entry = snippet_fixture_entry(
            "safe",
            "Hello {{name}}",
            false,
            true,
            vec![crate::plugins::snippets::SnippetFieldDefinition::new(
                "name",
            )],
            &[],
        );
        crate::plugins::snippets::save_snippets(&snippets_path, std::slice::from_ref(&entry))
            .expect("the Snippets fixture is writable");
        prepare_actual_snippet_dialog(&ctx, &mut app, &snippets_path);
        start_actual_snippet_jump_mode(&ctx, &mut app);
        assert!(!snippet_target_ids(&app, "Snippet entry").is_empty());

        app.snippet_dialog.test_request_removal(0);
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        let removal_owner = app.jump_mode_ui.frame_navigation_owner();
        let crate::gui::jump_mode::ui::NavigationOwner::SnippetRemoval {
            parent_instance,
            confirmation_instance,
        } = removal_owner
        else {
            panic!("the captured row confirmation owns the exact popup scope: {removal_owner:?}");
        };
        assert_eq!(
            Some(parent_instance),
            app.jump_mode_ui
                .dialog_instance(crate::gui::jump_mode::ui::NavigationDialogKind::Snippets)
        );
        assert_eq!(confirmation_instance, 1);
        assert!(snippet_target_ids(&app, "Snippet entry").is_empty());
        assert!(snippet_target_ids(&app, "Remove snippet").is_empty());
        assert!(snippet_target_ids(&app, "Edit snippet").is_empty());
        assert!(snippet_target_ids(&app, "Add snippet").is_empty());
        assert!(snippet_target_ids(&app, "Close snippets").is_empty());
        assert_eq!(snippet_target_ids(&app, "Confirm snippet removal").len(), 1);
        assert_eq!(snippet_target_ids(&app, "Cancel snippet removal").len(), 1);
        assert_eq!(
            crate::plugins::snippets::load_snippets(&snippets_path).unwrap(),
            std::slice::from_ref(&entry),
            "a pending confirmation is only a focus target until a later key"
        );

        let confirm_target = snippet_target_ids(&app, "Confirm snippet removal")[0].clone();
        let confirm_response = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.id() == &confirm_target)
            .expect("the child owner registered the actual Confirm response")
            .response_id();
        start_actual_root_jump_mode(&ctx, &mut app);
        let confirm_hint = snippet_hint_for_target(&app, &confirm_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![
                    egui::Event::Text(confirm_hint),
                    key_press(egui::Key::Enter, egui::Modifiers::NONE),
                ],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(
            crate::plugins::snippets::load_snippets(&snippets_path).unwrap(),
            std::slice::from_ref(&entry),
            "hint completion and a same-frame Enter cannot confirm removal"
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(confirm_response)
        );

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Key {
                    key: egui::Key::Enter,
                    physical_key: None,
                    pressed: true,
                    repeat: true,
                    modifiers: egui::Modifiers::NONE,
                }],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(
            crate::plugins::snippets::load_snippets(&snippets_path).unwrap(),
            std::slice::from_ref(&entry),
            "a held Enter repeat cannot cross the confirmation handoff"
        );
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(
            crate::plugins::snippets::load_snippets(&snippets_path)
                .unwrap()
                .is_empty(),
            "only the later distinct Enter confirms the captured fixture row"
        );

        app.snippet_dialog.test_cancel_removal();
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        app.begin_snippet_preview(entry.clone())
            .expect("the harmless fixture can open its preview prompt");
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert!(app.snippet_prompt_dialog.is_open());
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            crate::gui::jump_mode::ui::NavigationOwner::SnippetPrompt {
                generation: app
                    .snippet_prompt_dialog
                    .session()
                    .expect("Preview keeps its transient session")
                    .generation,
            }
        );
        assert!(snippet_target_ids(&app, "Snippet entry").is_empty());
        assert!(snippet_target_ids(&app, "Copy snippet").is_empty());
        assert_eq!(
            snippet_target_ids(&app, "Return to snippet editor").len(),
            1
        );
        assert!(app.snippet_dialog.open);
    }

    #[test]
    fn jump_mode_snippet_prompt_tracks_exact_generation_and_blocks_foreign_middle_owner() {
        use crate::gui::jump_mode::ui::NavigationOwner;

        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let private_alias = "private-snippet-alias";
        let private_body = "private-body-marker {{private_field_key}}";
        let private_default = "private-default-marker";
        let private_tag = "private-tag-marker";
        let mut private_field =
            crate::plugins::snippets::SnippetFieldDefinition::new("private_field_key");
        private_field.label = "Private field label".into();
        private_field.default_value = private_default.into();
        let private_entry = snippet_fixture_entry(
            private_alias,
            private_body,
            false,
            true,
            vec![private_field],
            &[private_tag],
        );
        request_test_prompt(&mut app, private_entry);
        let first_generation = app
            .snippet_prompt_dialog
            .session()
            .expect("the fixture opens a transient prompt")
            .generation;
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::SnippetPrompt {
                generation: first_generation,
            }
        );
        let first_targets: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .map(|target| target.id().clone())
            .collect();
        assert!(!first_targets.is_empty());
        for target in app.jump_mode_ui.retained_registry().targets() {
            let metadata = format!("{} {:?}", target.metadata().label(), target.id());
            for private_value in [
                private_alias,
                private_body,
                private_default,
                private_tag,
                "private_field_key",
                "Private field label",
            ] {
                assert!(
                    !metadata.contains(private_value),
                    "prompt target metadata leaked {private_value:?}"
                );
            }
        }
        assert!(!snippet_target_ids(&app, "Snippet input").is_empty());
        assert_eq!(snippet_target_ids(&app, "Copy snippet").len(), 1);
        assert_eq!(snippet_target_ids(&app, "Cancel snippet prompt").len(), 1);

        let mut replacement_field =
            crate::plugins::snippets::SnippetFieldDefinition::new("replacement_key");
        replacement_field.default_value = "replacement-default-marker".into();
        let replacement = snippet_fixture_entry(
            "replacement-alias",
            "replacement-body-marker {{replacement_key}}",
            false,
            true,
            vec![replacement_field],
            &[],
        );
        request_test_prompt(&mut app, replacement);
        let replacement_generation = app
            .snippet_prompt_dialog
            .session()
            .expect("replacing the prompt renews its session")
            .generation;
        assert_ne!(replacement_generation, first_generation);
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::SnippetPrompt {
                generation: replacement_generation,
            }
        );
        let replacement_targets: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .map(|target| target.id().clone())
            .collect();
        assert!(!replacement_targets.is_empty());
        assert!(
            first_targets
                .iter()
                .all(|old_target| !replacement_targets.contains(old_target)),
            "a replaced prompt cannot retain targets from its prior generation"
        );

        let foreign_window_id = egui::Id::new("m3b_foreign_middle_window");
        let draw_foreign_window = |app: &mut LauncherApp, ui: &mut egui::Ui| {
            app.render_root_ui(ui);
            egui::Window::new("Foreign owner")
                .id(foreign_window_id)
                .collapsible(false)
                .show(ui.ctx(), |ui| {
                    ui.label("This window owns foreground input.")
                });
        };
        app.run_root_frame_for_test_with(
            &ctx,
            actual_query_input(true),
            false,
            draw_foreign_window,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(
            crate::gui::jump_mode::ui::visible_top_middle_layer(&ctx),
            Some(egui::LayerId::new(egui::Order::Middle, foreign_window_id,)),
            "the fixture must put a real foreign Window above the prompt"
        );

        app.run_root_frame_for_test_with(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::CTRL)],
                ..actual_query_input(true)
            },
            false,
            draw_foreign_window,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.snippet_prompt_dialog.is_open());
        assert_eq!(app.snippet_prompt_dialog.feedback(), None);
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Blocked
        );
        assert!(app.jump_mode_ui.retained_registry().targets().is_empty());
    }

    #[test]
    fn jump_mode_snippet_prompt_escape_field_copy_hints_remain_focus_only_until_fresh_submit() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let entry = prompted_test_entry();
        let snippets_path = workspace
            .root()
            .join(crate::plugins::snippets::SNIPPETS_FILE)
            .to_string_lossy()
            .into_owned();
        crate::plugins::snippets::save_snippets(&snippets_path, &[])
            .expect("the isolated current store is empty until the fake submit seam");
        request_test_prompt(&mut app, entry.clone());
        let generation = app
            .snippet_prompt_dialog
            .session()
            .expect("the prompt session exists")
            .generation;
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert!(app.snippet_prompt_native_ui_owner_current(&ctx, true));
        let query_before = app.query.clone();

        start_actual_root_jump_mode(&ctx, &mut app);
        assert!(app.jump_mode_ui.active_session().is_some());
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.snippet_prompt_dialog.is_open());
        assert!(app.jump_mode_ui.active_session().is_none());
        assert_eq!(app.query, query_before);

        let field_target = snippet_target_ids(&app, "Snippet input")
            .into_iter()
            .find(|target| {
                matches!(
                    target.semantic(),
                    crate::gui::jump_mode::SemanticTargetId::Named(identity)
                        if identity.contains("field/0")
                )
            })
            .expect("the first actual editable field has a generic target identity");
        start_actual_root_jump_mode(&ctx, &mut app);
        let field_hint = snippet_hint_for_target(&app, &field_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(field_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(ctx.memory(|memory| {
            memory.has_focus(egui::Id::new(("snippet_prompt_field", generation, "name")))
        }));
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text("Ada".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(
            app.snippet_prompt_dialog
                .session()
                .and_then(|session| session.values.get("name"))
                .map(String::as_str),
            Some("Ada"),
            "native typing continues in the field after Jump focus"
        );

        let copy_target = snippet_target_ids(&app, "Copy snippet")
            .into_iter()
            .next()
            .expect("the enabled Copy action is a real response target");
        start_actual_root_jump_mode(&ctx, &mut app);
        let copy_hint = snippet_hint_for_target(&app, &copy_target);
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![
                    egui::Event::Text(copy_hint),
                    key_press(egui::Key::Enter, egui::Modifiers::CTRL),
                ],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(
            app.snippet_prompt_dialog.is_open(),
            "a Copy hint and same-frame Ctrl+Enter only focus the actual response"
        );
        assert_eq!(app.snippet_prompt_dialog.feedback(), None);
        assert_eq!(app.query, query_before);

        let mut copied = Vec::new();
        let mut submit_result = None;
        let output = ctx.run_ui(
            prompt_raw_input(vec![key_press(egui::Key::Enter, egui::Modifiers::CTRL)]),
            |ctx| {
                assert!(app.snippet_prompt_native_ui_owner_current(ctx, true));
                assert!(app.route_snippet_prompt_keyboard_with(ctx, |app| {
                    submit_result = Some(app.submit_snippet_prompt_with_test_backends(
                        |alias| (alias == entry.alias).then(|| entry.clone()).ok_or(()),
                        |text| {
                            copied.push(text.to_owned());
                            Ok(())
                        },
                    ));
                }));
                assert!(!ctx.input(|input| input.key_pressed(egui::Key::Enter)));
            },
        );
        output.drop_without_applying_deltas();
        assert_eq!(copied, ["Hello Ada\n"]);
        assert!(
            submit_result
                .expect("the fresh native key submits once")
                .is_ok()
        );
        assert!(app.snippet_prompt_dialog.session().is_none());
        assert_eq!(app.query, query_before);
    }

    #[test]
    fn jump_mode_snippet_prompt_sequence_preflight_keeps_native_keys_without_jump_targets() {
        use crate::gui::jump_mode::ui::NavigationOwner;

        let ctx = egui::Context::default();
        let (_workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let entry = prompted_test_entry();
        let sequence = crate::paste_sequence::Sequence {
            id: crate::paste_sequence::SequenceId::from_raw(1)
                .expect("the safe preflight fixture has a nonzero ID"),
            name: "Safe prompt preflight".into(),
            hotkey: None,
            mode: crate::paste_sequence::PlaybackMode::ManualAdvance,
            delay_ms: 0,
            steps: vec![crate::paste_sequence::Step::SnippetRef {
                alias: entry.alias.clone(),
            }],
        };
        let target = crate::paste_sequence::SequenceTarget::from_external_window(
            crate::active_window::ExternalForegroundWindow {
                hwnd: 111,
                process_id: 222,
                thread_id: 333,
                title: None,
            },
            444,
        )
        .expect("the deterministic external target is valid");
        let flow = crate::paste_sequence::SequencePreflight::begin(
            sequence,
            std::slice::from_ref(&entry),
            &[],
            crate::paste_sequence::SequenceInvocationContext::new(
                chrono::DateTime::parse_from_rfc3339("2024-01-02T03:04:05+00:00")
                    .expect("the fixed preflight timestamp is valid"),
                None,
                target,
            ),
        )
        .expect("the isolated snippet reference can start in-memory preflight");
        app.snippet_prompt_dialog
            .begin_sequence_preflight(&ctx, flow)
            .expect("the first prompted step opens normally");
        let generation = app
            .snippet_prompt_dialog
            .session()
            .expect("preflight has a current prompt")
            .generation;
        let first_field = egui::Id::new(("snippet_prompt_field", generation, "name"));
        let next_field = egui::Id::new(("snippet_prompt_field", generation, "message"));
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert!(app.snippet_prompt_dialog.is_sequence_preflight());
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Blocked
        );
        assert!(app.jump_mode_ui.retained_registry().targets().is_empty());
        assert!(ctx.memory(|memory| memory.has_focus(first_field)));

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Tab, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.snippet_prompt_dialog.is_open());
        assert!(app.snippet_prompt_dialog.is_sequence_preflight());
        assert!(ctx.memory(|memory| memory.has_focus(next_field)));
        assert!(app.jump_mode_ui.retained_registry().targets().is_empty());
    }

    fn seed_actual_file_search_filename_results(
        app: &mut LauncherApp,
        search_id: crate::file_search::model::SearchId,
        paths: &[std::path::PathBuf],
    ) {
        use crate::file_search::model::{
            FileKind, FilenameRank, FilenameResult, SearchEvent, SearchResult,
        };

        let state = &mut app.file_search_dialog;
        state.selected_mode = crate::gui::file_search_dialog::FileSearchMode::Filename;
        state.active_search_id = Some(search_id);
        state.current_status = crate::file_search::model::SearchStatus::Running;
        state.clear_results_and_selection();
        state.active_search_id = Some(search_id);
        for (arrival_index, path) in paths.iter().enumerate() {
            state.apply_event(SearchEvent::Result {
                id: search_id,
                result: SearchResult::Filename(FilenameResult {
                    path: path.clone(),
                    file_name: path
                        .file_name()
                        .unwrap_or_default()
                        .to_string_lossy()
                        .into_owned(),
                    parent_directory: path.parent().map(std::path::Path::to_path_buf),
                    kind: FileKind::Other,
                    size: None,
                    modified: None,
                    rank: FilenameRank::ExactFilename,
                    match_quality: FilenameRank::ExactFilename,
                    filename_match_ranges: Vec::new(),
                    path_match_ranges: Vec::new(),
                    arrival_index,
                }),
            });
        }
        state.apply_event(SearchEvent::Completed { id: search_id });
    }

    fn seed_actual_file_search_content_result(
        app: &mut LauncherApp,
        search_id: crate::file_search::model::SearchId,
        path: &std::path::Path,
        line: &str,
    ) {
        use crate::file_search::model::{
            ContentFileResult, ContentMatch, SearchEvent, SearchResult,
        };

        let state = &mut app.file_search_dialog;
        state.selected_mode = crate::gui::file_search_dialog::FileSearchMode::Content;
        state.active_search_id = Some(search_id);
        state.current_status = crate::file_search::model::SearchStatus::Running;
        state.clear_results_and_selection();
        state.active_search_id = Some(search_id);
        state.apply_event(SearchEvent::Result {
            id: search_id,
            result: SearchResult::ContentFile(ContentFileResult {
                path: path.to_path_buf(),
                file_name: path
                    .file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .into_owned(),
                modified: None,
                filename_relevance: None,
                arrival_index: 0,
                total_matches: 1,
                matches: vec![ContentMatch::new(1, line.to_owned(), 0, line.len())],
                truncated: false,
            }),
        });
        state.apply_event(SearchEvent::Completed { id: search_id });
    }

    fn actual_file_search_result_target_ids(
        app: &LauncherApp,
        label: &str,
    ) -> Vec<crate::gui::jump_mode::TargetId> {
        app.jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == label)
            .map(|target| target.metadata().id().clone())
            .collect()
    }

    #[test]
    fn jump_mode_file_search_form_registers_visible_controls_by_mode() {
        use crate::gui::jump_mode::ui::NavigationOwner;

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_file_search_dialog(&ctx, &mut app, workspace.root());

        let initial_labels: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .metadata()
            .map(|target| target.label().to_owned())
            .collect();
        assert!(
            initial_labels.iter().any(|target| target == "Diagnostics"),
            "the diagnostics heading is registered while it is visible: {initial_labels:?}"
        );

        expand_file_search_header(&ctx, &app, "Filters");
        for _ in 0..3 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }

        let filename_labels: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .metadata()
            .map(|target| target.label().to_owned())
            .collect();
        for label in [
            "Search query",
            "Filename",
            "Content",
            "Global",
            "Directory",
            "Case-sensitive",
            "Include hidden",
            "Add folder",
            "Cancel",
            "Export",
            "Filters",
            "Ranked substring",
            "Fuzzy",
        ] {
            assert!(
                filename_labels.iter().any(|target| target == label),
                "missing {label:?}: {filename_labels:?}"
            );
        }
        for disabled in ["Search", "Open", "Clear filter"] {
            assert!(
                !filename_labels.iter().any(|target| target == disabled),
                "disabled target {disabled:?} was registered"
            );
        }

        app.file_search_dialog.selected_mode =
            crate::gui::file_search_dialog::FileSearchMode::Content;
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        let content_labels: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .metadata()
            .map(|target| target.label().to_owned())
            .collect();
        for label in ["Exact phrase", "Match any term", "Whole word"] {
            assert!(
                content_labels.iter().any(|target| target == label),
                "missing {label:?}: {content_labels:?}"
            );
        }
        for inactive in ["Ranked substring", "Fuzzy"] {
            assert!(
                !content_labels.iter().any(|target| target == inactive),
                "inactive target {inactive:?} was registered"
            );
        }
        assert_ne!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Blocked
        );
        drop(workspace);
    }

