    #[test]
    fn jump_mode_file_search_form_background_owner_refuses_focused_field_and_button() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_file_search_dialog(&ctx, &mut app, workspace.root());
        expand_file_search_header(&ctx, &app, "Filters");
        for _ in 0..3 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        app.file_search_dialog.current_status = crate::file_search::model::SearchStatus::Running;
        app.file_search_dialog.active_search_id = Some(crate::file_search::model::SearchId(42));
        let included_extensions_id = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Include extensions")
            .expect("the expanded File Search filters show the include field")
            .response_id();
        let cancel_id = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Cancel")
            .expect("Cancel is a visible File Search target")
            .response_id();

        let unsupported_layer = egui::LayerId::new(
            egui::Order::Middle,
            egui::Id::new("unsupported-file-search-cover"),
        );
        let render_cover = |app: &mut LauncherApp, input: egui::RawInput| {
            let (output, _) = app.run_root_frame_for_test_with(&ctx, input, false, |app, ui| {
                app.render_root_ui(ui);
                egui::Window::new("Unsupported File Search cover")
                    .id(unsupported_layer.id)
                    .show(ui.ctx(), |_| {});
                ui.ctx().move_to_top(unsupported_layer);
            });
            output.drop_without_applying_deltas();
        };
        render_cover(&mut app, actual_query_input(true));
        render_cover(&mut app, actual_query_input(true));
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            crate::gui::jump_mode::ui::NavigationOwner::Blocked
        );

        let query_id = crate::gui::file_search_dialog::FileSearchDialogState::search_field_id();
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        render_cover(
            &mut app,
            egui::RawInput {
                events: vec![
                    egui::Event::Text("background".into()),
                    key_press(egui::Key::Enter, egui::Modifiers::NONE),
                ],
                ..actual_query_input(true)
            },
        );
        assert!(app.file_search_dialog.search_text.is_empty());
        assert_eq!(app.file_search_coordinator.active_search_id(), None);

        let included_extensions_before = app
            .file_search_dialog
            .ui_preferences
            .included_extensions
            .clone();
        ctx.memory_mut(|memory| memory.request_focus(included_extensions_id));
        render_cover(
            &mut app,
            egui::RawInput {
                events: vec![egui::Event::Text("blocked".into())],
                ..actual_query_input(true)
            },
        );
        assert!(!ctx.memory(|memory| memory.has_focus(included_extensions_id)));
        assert_eq!(
            app.file_search_dialog.ui_preferences.included_extensions, included_extensions_before,
            "a focused advanced field cannot mutate behind an unknown window"
        );

        ctx.memory_mut(|memory| memory.request_focus(cancel_id));
        render_cover(
            &mut app,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
        );
        assert_eq!(
            app.file_search_dialog.current_status,
            crate::file_search::model::SearchStatus::Running,
            "a focused background Cancel button cannot run its keyboard action"
        );
        assert_eq!(
            app.file_search_dialog.active_search_id,
            Some(crate::file_search::model::SearchId(42))
        );
        assert!(app.test_activation_trace.is_empty());
        drop(workspace);
    }

    #[test]
    fn jump_mode_file_search_lifecycle_reopen_rejects_stale_targets() {
        use crate::gui::jump_mode::SurfaceId;
        use crate::gui::jump_mode::ui::{NavigationDialogKind, NavigationOwner};

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        prepare_actual_file_search_dialog(&ctx, &mut app, workspace.root());

        let original_query_target = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Search query")
            .expect("the open File Search dialog registers its query field")
            .id()
            .clone();
        let original_form_generation = app.file_search_dialog.jump_mode_target_generation();

        app.file_search_dialog
            .open_with_mode(crate::gui::file_search_dialog::FileSearchMode::Content);
        app.file_search_dialog.show_ripgrep_missing_prompt = true;
        for _ in 0..3 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert!(
            app.file_search_dialog.jump_mode_target_generation() > original_form_generation,
            "mode changes advance the live form generation"
        );
        let prompt_labels: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .metadata()
            .map(|target| target.label().to_owned())
            .collect();
        assert!(prompt_labels.iter().any(|label| label == "Locate ripgrep"));
        assert!(prompt_labels.iter().any(|label| label == "Dismiss"));

        let picker_layer = egui::LayerId::new(
            egui::Order::Middle,
            egui::Id::new("file-search-foreign-picker-window"),
        );
        let render_with_picker = |app: &mut LauncherApp, input: egui::RawInput| {
            let (output, _) = app.run_root_frame_for_test_with(&ctx, input, false, |app, ui| {
                app.render_root_ui(ui);
                egui::Window::new("File Search picker window")
                    .id(picker_layer.id)
                    .show(ui.ctx(), |_| {});
                ui.ctx().move_to_top(picker_layer);
            });
            output.drop_without_applying_deltas();
        };
        for _ in 0..2 {
            render_with_picker(&mut app, actual_query_input(true));
        }
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Blocked,
            "a foreign picker window above the inline rg notice blocks File Search hints"
        );

        app.file_search_dialog.open = false;
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Root
        );
        assert!(
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .all(|target| {
                    !matches!(
                        target.id().surface(),
                        SurfaceId::Dialog { kind, .. } if kind == "file-search"
                    )
                }),
            "closing File Search clears its current target identities"
        );

        app.file_search_dialog.open();
        for _ in 0..4 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::FileSearch,
                instance: 2,
            }
        );
        let reopened_query_target = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Search query")
            .expect("the reopened dialog registers its current query field")
            .id();
        assert_ne!(reopened_query_target, &original_query_target);
        assert_eq!(
            reopened_query_target.surface(),
            &SurfaceId::dialog("file-search", 2)
        );
        assert!(
            app.jump_mode_ui
                .retained_registry()
                .get(&original_query_target)
                .is_none()
        );

        app.set_jump_mode_enabled(false);
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        assert!(
            app.jump_mode_ui.retained_registry().is_empty(),
            "default-off File Search keeps ordinary UI visible and registers no Jump Mode targets"
        );
        drop(workspace);
    }

    #[test]
    fn jump_mode_file_search_results_use_opaque_duplicate_path_ids_and_select_without_opening() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let first_path = workspace.root().join("α").join("同じ名前.txt");
        let second_path = workspace.root().join("β").join("同じ名前.txt");
        seed_actual_file_search_filename_results(
            &mut app,
            crate::file_search::model::SearchId(31),
            &[first_path.clone(), second_path.clone()],
        );
        prepare_actual_file_search_dialog(&ctx, &mut app, workspace.root());
        start_actual_root_jump_mode(&ctx, &mut app);

        let result_targets = actual_file_search_result_target_ids(&app, "Filename result");
        assert_eq!(result_targets.len(), 2);
        assert_ne!(result_targets[0], result_targets[1]);
        let target_metadata: Vec<_> = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == "Filename result")
            .map(|target| {
                assert!(!format!("{:?}", target.metadata().id()).contains("同じ名前"));
                target.response_id()
            })
            .collect();

        let result_hint = dialog_hint_for_label(&app, "Filename result");
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(result_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();

        let selected = app
            .file_search_dialog
            .selected_result()
            .expect("Jump Mode selects a current filename row");
        assert!([&first_path, &second_path].contains(&&selected.row_id.path));
        assert!(!app.file_search_dialog.preview_dialog.open);
        assert!(app.file_search_dialog.warning_error_message.is_none());
        assert!(app.test_activation_trace.is_empty());
        let focused_id = ctx.memory(|memory| memory.focused());
        assert!(
            target_metadata
                .iter()
                .any(|response_id| Some(*response_id) == focused_id)
        );
        drop(workspace);
    }

    #[test]
    fn jump_mode_file_search_results_focus_then_enter_previews_one_content_match() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);

        let content_path = workspace.root().join("needle_source.rs");
        let source_line = "needle content in an isolated fixture";
        std::fs::write(&content_path, format!("{source_line}\nsecond line\n"))
            .expect("the fixture source file should be writable");
        seed_actual_file_search_content_result(
            &mut app,
            crate::file_search::model::SearchId(32),
            &content_path,
            source_line,
        );
        prepare_actual_file_search_dialog(&ctx, &mut app, workspace.root());
        start_actual_root_jump_mode(&ctx, &mut app);

        assert_eq!(
            actual_file_search_result_target_ids(&app, "Content match").len(),
            1
        );
        let result_hint = dialog_hint_for_label(&app, "Content match");
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text(result_hint)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.file_search_dialog.selected_result().is_some());
        assert!(!app.file_search_dialog.preview_dialog.open);
        assert!(
            app.file_search_dialog
                .preview_dialog
                .current_request
                .is_none()
        );

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        let request = app
            .file_search_dialog
            .preview_dialog
            .current_request
            .as_ref()
            .expect("a later Enter opens the selected Content preview")
            .clone();
        assert!(app.file_search_dialog.preview_dialog.open);
        assert_eq!(request.path, content_path);
        assert_eq!(request.selected_match.as_ref().unwrap().line, 1);
        assert_eq!(
            request
                .selected_match
                .as_ref()
                .unwrap()
                .source_line
                .as_deref(),
            Some(source_line)
        );
        assert_eq!(
            app.file_search_dialog
                .preview_dialog
                .selected_match
                .as_ref()
                .unwrap()
                .line_number,
            1
        );
        assert!(app.test_activation_trace.is_empty());

        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert_eq!(
            app.file_search_dialog
                .preview_dialog
                .current_request
                .as_ref(),
            Some(&request),
            "the consumed Enter does not trigger a second preview on a later frame"
        );
        drop(workspace);
    }

