    fn run_embedded_root_dialog_frame(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        input: egui::RawInput,
    ) {
        let mut frame = eframe::Frame::_new_kittest();
        let mut passes = 0;
        let output = ctx.run_ui(input, |ui| {
            app.begin_root_frame_logic(ui.ctx(), &mut frame);
            app.render_root_ui(ui);
            passes += 1;
        });
        app.finish_ui_frame_receipt();
        app.complete_jump_mode_frame(ctx);
        assert!(passes > 0, "the embedded root fixture renders a pass");
        output.drop_without_applying_deltas();
    }

    fn start_embedded_root_jump_mode(ctx: &egui::Context, app: &mut LauncherApp) {
        run_embedded_root_dialog_frame(
            ctx,
            app,
            egui::RawInput {
                events: vec![
                    key_press(egui::Key::Space, egui::Modifiers::SHIFT),
                    egui::Event::Text(" ".into()),
                ],
                ..actual_query_input(true)
            },
        );
        assert!(app.jump_mode_ui.active_session().is_some());
        run_embedded_root_dialog_frame(
            ctx,
            app,
            egui::RawInput {
                events: vec![key_release(egui::Key::Space, egui::Modifiers::SHIFT)],
                ..actual_query_input(true)
            },
        );
    }

    fn wait_for_timer_sound_option_target(
        ctx: &egui::Context,
        app: &mut LauncherApp,
    ) -> crate::gui::jump_mode::TargetId {
        use crate::gui::jump_mode::TargetKind;
        use crate::gui::jump_mode::ui::NavigationOwner;

        let timer_instance = app.jump_mode_ui.timer_instance();
        for _ in 0..8 {
            let owner = app.jump_mode_ui.frame_navigation_owner();
            let target = app
                .jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .find(|target| {
                    target.metadata().label() == "Sound: Alarm.wav"
                        && target.metadata().kind() == TargetKind::Selectable
                        && target.eligible()
                        && owner
                            == (NavigationOwner::Timer {
                                instance: timer_instance,
                            })
                        && owner.owns_surface(target.id().surface())
                });
            if let Some(target) = target {
                return target.id().clone();
            }
            run_dialog_frame(ctx, app);
        }

        panic!(
            "Timer sound option was not published as an eligible popup target; owner={:?}, targets={:?}",
            app.jump_mode_ui.frame_navigation_owner(),
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .map(|target| {
                    (
                        target.metadata().label(),
                        target.metadata().kind(),
                        target.id().surface(),
                        target.eligible(),
                    )
                })
                .collect::<Vec<_>>()
        );
    }

