    #[test]
    fn opening_settings_on_a_discarded_root_pass_cancels_background_navigation() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        start_actual_root_jump_mode(&ctx, &mut app);
        assert!(app.jump_mode_ui.active_session().is_some());

        let mut opened_settings = false;
        let (output, passes) =
            app.run_root_frame_for_test_with(&ctx, actual_query_input(true), true, |app, ui| {
                if !opened_settings {
                    app.show_settings = true;
                    opened_settings = true;
                }
                app.render_root_ui(ui);
            });
        output.drop_without_applying_deltas();

        assert!(passes >= 2, "the first pass is deliberately discarded");
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(app.jump_mode_ui.retained_registry().is_empty());
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            crate::gui::jump_mode::ui::NavigationOwner::Blocked
        );
        assert!(
            !ctx.memory(|memory| memory.has_focus(egui::Id::new("query_input"))),
            "opening Settings yields the background query's native focus"
        );
        assert!(app.test_activation_trace.is_empty());
        drop(workspace);
    }

    #[test]
    fn actual_root_navigation_owner_follows_settings_and_foreign_window_layers() {
        use crate::gui::jump_mode::ui::{NavigationOwner, settings_layer_id};

        fn render_with_unsupported_window(
            ctx: &egui::Context,
            app: &mut LauncherApp,
            raise_settings: bool,
            focus_note: bool,
        ) -> NavigationOwner {
            let note_layer = egui::LayerId::new(
                egui::Order::Middle,
                egui::Id::new("unsupported_note_window"),
            );
            let (output, _) = app.run_root_frame_for_test_with(
                ctx,
                actual_query_input(true),
                false,
                |app, ui| {
                    app.render_root_ui(ui);
                    egui::Window::new("Unsupported note")
                        .id(egui::Id::new("unsupported_note_window"))
                        .show(ui.ctx(), |ui| {
                            let mut note_text = String::new();
                            let response = ui.add(
                                egui::TextEdit::singleline(&mut note_text)
                                    .id(egui::Id::new("unsupported_note_editor")),
                            );
                            if focus_note {
                                response.request_focus();
                            }
                        });
                    ui.ctx().move_to_top(if raise_settings {
                        settings_layer_id()
                    } else {
                        note_layer
                    });
                },
            );
            output.drop_without_applying_deltas();
            app.jump_mode_ui.frame_navigation_owner()
        }

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        app.show_settings = true;

        // Newly-created windows are retained at their creation order first.
        // Raising Settings only changes the completed layer order, so the
        // second frame blocks the owner transition before a third can use it.
        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, false),
            NavigationOwner::Blocked
        );
        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, false),
            NavigationOwner::Blocked,
        );
        assert_eq!(
            crate::gui::jump_mode::ui::visible_top_middle_layer(&ctx),
            Some(settings_layer_id()),
            "the manually raised Settings layer is retained after the transition frame"
        );
        assert_eq!(
            crate::gui::jump_mode::ui::resolve_layer_navigation_owner(
                &ctx,
                crate::gui::jump_mode::ui::NavigationWindows {
                    settings: app
                        .show_settings
                        .then_some(app.jump_mode_ui.settings_instance()),
                    notes: None,
                    todo: None,
                    timer: None,
                    paste_sequence: None,
                    mkmacro: None,
                    dialogs: [None; crate::gui::jump_mode::ui::NavigationDialogKind::ALL.len()],
                },
            ),
            NavigationOwner::Settings { instance: 1 },
            "the retained Settings layer owns navigation after the transition frame"
        );
        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, false),
            NavigationOwner::Settings { instance: 1 },
        );

        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, false, false),
            NavigationOwner::Blocked,
            "an unsupported ordinary window above Settings blocks root navigation"
        );

        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, false),
            NavigationOwner::Blocked
        );
        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, false),
            NavigationOwner::Settings { instance: 1 },
            "Settings above a supported-but-unintegrated window owns navigation"
        );
        assert_eq!(
            render_with_unsupported_window(&ctx, &mut app, true, true),
            NavigationOwner::Blocked,
            "focus inside a foreign window blocks even when Settings is foremost"
        );
        assert!(app.test_activation_trace.is_empty());
        drop(workspace);
    }

    fn batch_rename_test_frame(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        events: Vec<egui::Event>,
    ) {
        let output = app.run_root_frame_for_test(
            ctx,
            egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1440.0, 1100.0),
                )),
                events,
                ..actual_query_input(true)
            },
            false,
        );
        output.0.drop_without_applying_deltas();
    }

    fn prepare_batch_rename_generated_fixture(
        ctx: &egui::Context,
    ) -> (
        crate::performance::workloads::IsolatedWorkspace,
        LauncherApp,
        std::path::PathBuf,
        tempfile::TempDir,
    ) {
        let repository_root =
            std::env::current_dir().expect("read repository root before isolation");
        let (workspace, mut app) = root_list_test_app(ctx, Vec::new());
        let scan_parent = repository_root.join("target/productivity_expansion");
        std::fs::create_dir_all(&scan_parent).expect("create repository-local scan fixture parent");
        let root_guard = tempfile::Builder::new()
            .prefix("batch_rename_jump_")
            .tempdir_in(&scan_parent)
            .expect("create disposable native scan root");
        let root = root_guard.path().to_path_buf();
        std::fs::write(root.join("alpha.txt"), b"alpha fixture").unwrap();
        std::fs::write(root.join("beta.txt"), b"beta fixture").unwrap();

        app.set_jump_mode_enabled(true);
        app.batch_rename_dialog.open = true;
        prepare_actual_query_frame(ctx, &mut app);
        app.handle_batch_rename_ui_command(crate::gui::BatchRenameUiCommand::SelectRoot(
            root.clone(),
        ));
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            app.poll_batch_rename_runtime(ctx);
            let runtime = app.batch_rename_runtime_snapshot();
            if !app.batch_rename_dialog.has_pending_scan() && runtime.journal_ready {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the generated read-only scan and recovery journal should settle"
            );
            thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(
            app.batch_rename_dialog.test_scan_status(),
            Some(crate::file_operations::RenameScanStatus::Complete),
            "the generated root must produce a complete scan before testing visible rows: {}",
            app.batch_rename_dialog.test_scan_diagnostic()
        );
        assert!(
            app.batch_rename_dialog.has_accepted_snapshot(),
            "a complete scan must be accepted by the current session: {}",
            app.batch_rename_dialog.test_scan_diagnostic()
        );
        for _ in 0..2 {
            batch_rename_test_frame(ctx, &mut app, Vec::new());
        }
        (workspace, app, root, root_guard)
    }

    fn batch_rename_target_by_label(
        app: &LauncherApp,
        label: &str,
    ) -> crate::gui::jump_mode::ui::RegisteredTarget {
        app.jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == label)
            .unwrap_or_else(|| panic!("missing current Batch Rename target: {label}"))
            .clone()
    }

    fn batch_rename_select_target_for_ref(
        app: &LauncherApp,
        entry_ref: crate::batch_rename::SnapshotEntryRef,
    ) -> crate::gui::jump_mode::ui::RegisteredTarget {
        use crate::gui::jump_mode::SemanticTargetId;

        let local_identity = format!("entry/{}/select", entry_ref.0);
        let suffix = format!("{}:{local_identity}", local_identity.len());
        app.jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| {
                target.metadata().label() == "Select file"
                    && matches!(
                        target.id().semantic(),
                        SemanticTargetId::Named(identity) if identity.ends_with(&suffix)
                    )
            })
            .unwrap_or_else(|| panic!("missing Select target for opaque row {}", entry_ref.0))
            .clone()
    }

    fn batch_rename_start_hints(ctx: &egui::Context, app: &mut LauncherApp) {
        batch_rename_test_frame(
            ctx,
            app,
            vec![
                key_press(egui::Key::Space, egui::Modifiers::SHIFT),
                egui::Event::Text(" ".into()),
            ],
        );
    }

    fn batch_rename_complete_hint(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        target: &crate::gui::jump_mode::ui::RegisteredTarget,
    ) {
        let hint = app
            .jump_mode_ui
            .active_session()
            .expect("leader starts a Jump session")
            .hint_map()
            .hint_for(target.id())
            .expect("the current target receives a hint")
            .as_str()
            .to_owned();
        batch_rename_test_frame(
            ctx,
            app,
            vec![key_release(egui::Key::Space, egui::Modifiers::SHIFT)],
        );
        batch_rename_test_frame(ctx, app, vec![egui::Event::Text(hint)]);
    }

    #[test]
    fn jump_mode_batch_rename_rows_focus_only_and_native_ids_follow_sort() {
        use crate::gui::jump_mode::TargetKind;

        let ctx = egui::Context::default();
        let (workspace, mut app, root, root_guard) = prepare_batch_rename_generated_fixture(&ctx);
        let original_bytes = ["alpha.txt", "beta.txt"]
            .into_iter()
            .map(|name| std::fs::read(root.join(name)).unwrap())
            .collect::<Vec<_>>();
        let refs = app.batch_rename_dialog.test_visible_file_entry_refs();
        assert_eq!(refs.len(), 2);
        let first = batch_rename_select_target_for_ref(&app, refs[0]);
        assert_eq!(first.metadata().kind(), TargetKind::Checkbox);
        assert!(first.enabled());
        assert!(first.clipped_rect().width() > 0.0 && first.clipped_rect().height() > 0.0);
        let id_before = refs
            .iter()
            .map(|entry_ref| {
                (
                    entry_ref.0,
                    batch_rename_select_target_for_ref(&app, *entry_ref).response_id(),
                )
            })
            .collect::<HashMap<_, _>>();
        for target in app.jump_mode_ui.retained_registry().targets() {
            if matches!(target.metadata().label(), "Include file" | "Select file") {
                let crate::gui::jump_mode::SemanticTargetId::Named(identity) =
                    target.id().semantic()
                else {
                    panic!("row metadata is represented by an opaque identity")
                };
                assert!(!identity.contains("alpha.txt"));
                assert!(!identity.contains("beta.txt"));
            }
        }

        batch_rename_start_hints(&ctx, &mut app);
        batch_rename_complete_hint(&ctx, &mut app, &first);
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(ctx.memory(|memory| memory.has_focus(first.response_id())));
        assert!(!app.batch_rename_dialog.test_is_selected(refs[0]));
        assert_eq!(
            ["alpha.txt", "beta.txt"]
                .into_iter()
                .map(|name| std::fs::read(root.join(name)).unwrap())
                .collect::<Vec<_>>(),
            original_bytes,
            "focusing a row does not change selection or files"
        );

        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Space, egui::Modifiers::NONE)],
        );
        assert!(app.batch_rename_dialog.test_is_selected(refs[0]));
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Space, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        let before_sort = refs
            .iter()
            .map(|entry_ref| {
                let target = batch_rename_select_target_for_ref(&app, *entry_ref);
                (entry_ref.0, (target.id().clone(), target.response_id()))
            })
            .collect::<HashMap<_, _>>();

        app.batch_rename_dialog.test_reverse_filename_order();
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            app.batch_rename_dialog.test_visible_file_entry_refs(),
            refs.iter().rev().copied().collect::<Vec<_>>(),
            "the fixture changed the displayed sort order"
        );
        for entry_ref in &refs {
            let target = batch_rename_select_target_for_ref(&app, *entry_ref);
            let (old_target_id, old_response_id) = &before_sort[&entry_ref.0];
            assert_eq!(
                target.response_id(),
                *old_response_id,
                "the actual checkbox response ID follows its entry through sorting"
            );
            assert_ne!(target.id(), old_target_id, "sort renews target authority");
            assert!(
                app.jump_mode_ui
                    .retained_registry()
                    .targets()
                    .iter()
                    .all(|current| current.id() != old_target_id),
                "the pre-sort target is absent from the renewed registry"
            );
        }
        assert_eq!(
            batch_rename_select_target_for_ref(&app, refs[0]).response_id(),
            id_before[&refs[0].0],
            "a row's native checkbox identity is stable from first paint and after sorting"
        );
        assert_eq!(
            ["alpha.txt", "beta.txt"]
                .into_iter()
                .map(|name| std::fs::read(root.join(name)).unwrap())
                .collect::<Vec<_>>(),
            original_bytes
        );
        app.shutdown_batch_rename_scanner();
        drop(root_guard);
        drop(workspace);
    }

    #[test]
    fn jump_mode_file_operations_integration_sort_headers_are_focus_only_and_current() {
        use crate::gui::jump_mode::TargetKind;

        let ctx = egui::Context::default();
        let (workspace, mut app, root, root_guard) = prepare_batch_rename_generated_fixture(&ctx);
        let original_bytes = ["alpha.txt", "beta.txt"]
            .into_iter()
            .map(|name| std::fs::read(root.join(name)).unwrap())
            .collect::<Vec<_>>();
        let before_rows = app.batch_rename_dialog.test_visible_file_entry_refs();
        assert_eq!(before_rows.len(), 2);
        let row_before_sort = batch_rename_select_target_for_ref(&app, before_rows[0]);

        let sort_target = batch_rename_target_by_label(&app, "Sort by original filename");
        assert_eq!(sort_target.metadata().kind(), TargetKind::Button);
        assert!(sort_target.enabled());
        assert!(sort_target.clipped_rect().width() > 0.0);
        assert!(sort_target.clipped_rect().height() > 0.0);
        let safety_target = batch_rename_target_by_label(&app, "Batch rename safety and recovery");
        assert_eq!(safety_target.metadata().kind(), TargetKind::Button);
        assert!(safety_target.enabled());

        batch_rename_start_hints(&ctx, &mut app);
        batch_rename_complete_hint(&ctx, &mut app, &sort_target);
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(ctx.memory(|memory| memory.has_focus(sort_target.response_id())));
        assert_eq!(
            app.batch_rename_dialog.test_visible_file_entry_refs(),
            before_rows,
            "completing the hint focuses the sort header without changing the table"
        );
        assert_eq!(
            ["alpha.txt", "beta.txt"]
                .into_iter()
                .map(|name| std::fs::read(root.join(name)).unwrap())
                .collect::<Vec<_>>(),
            original_bytes,
            "focus-only navigation does not touch generated files"
        );

        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(&ctx, &mut app, Vec::new());

        let sort_after_first_activation =
            batch_rename_target_by_label(&app, "Sort by original filename");
        assert_eq!(
            sort_after_first_activation.response_id(),
            sort_target.response_id(),
            "the actual native header control keeps its identity as sort authority renews"
        );
        assert_eq!(
            sort_after_first_activation.id(),
            sort_target.id(),
            "the static sort control remains current through its own sort action"
        );
        assert_ne!(
            batch_rename_select_target_for_ref(&app, before_rows[0]).id(),
            row_before_sort.id(),
            "sorting renews row semantic authority independently of stable headers"
        );
        assert!(
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .all(|target| target.id() != row_before_sort.id())
        );

        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            app.batch_rename_dialog.test_visible_file_entry_refs(),
            before_rows.iter().rev().copied().collect::<Vec<_>>(),
            "a later native activation changes the selected column to descending order"
        );
        assert_eq!(
            ["alpha.txt", "beta.txt"]
                .into_iter()
                .map(|name| std::fs::read(root.join(name)).unwrap())
                .collect::<Vec<_>>(),
            original_bytes,
            "sorting remains a read-only file operation"
        );
        assert!(app.test_activation_trace.is_empty());
        app.shutdown_batch_rename_scanner();
        drop(root_guard);
        drop(workspace);
    }

    #[test]
    fn jump_mode_batch_rename_confirmation_apply_hint_requires_fresh_cancel() {
        use crate::gui::jump_mode::{SurfaceId, ui::NavigationOwner};

        let ctx = egui::Context::default();
        let (workspace, mut app, root, root_guard) = prepare_batch_rename_generated_fixture(&ctx);
        ctx.global_style_mut(|style| {
            style.scroll_animation = egui::style::ScrollAnimation::none();
        });
        let original = std::fs::read(root.join("alpha.txt")).unwrap();
        let entry_ref = app
            .batch_rename_dialog
            .test_prepare_ready_apply_preview()
            .expect("the generated fixture creates one ready, selected preview action");
        assert!(app.batch_rename_dialog.test_is_selected(entry_ref));
        app.batch_rename_dialog.test_reveal_apply_target();
        // Pass A queues the actual Apply response's scroll target. Pass B
        // advances the offset after constructing content at the old scroll
        // position; pass C collects targets with the newly visible geometry.
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        batch_rename_test_frame(&ctx, &mut app, Vec::new());
        let apply = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Apply selected renames")
            .cloned();
        assert!(
            apply.is_some(),
            "Apply should be a current visible target; owner={:?}, top_layer={:?}, native_owner={}, runtime=(journal_ready={}, operation_active={}, receipt_statuses={:?}), scan={}, targets={:?}",
            app.jump_mode_ui.frame_navigation_owner(),
            crate::gui::jump_mode::ui::visible_top_middle_layer(&ctx),
            app.batch_rename_native_ui_owner_current(&ctx, true),
            app.batch_rename_runtime_snapshot().journal_ready,
            app.batch_rename_runtime_snapshot().operation_active,
            app.batch_rename_runtime_snapshot()
                .receipts
                .iter()
                .map(|receipt| receipt.status())
                .collect::<Vec<_>>(),
            app.batch_rename_dialog.test_scan_diagnostic(),
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .map(|target| target.metadata().label())
                .collect::<Vec<_>>()
        );
        let apply = apply.expect("asserted current Apply target");
        assert!(apply.enabled());
        batch_rename_start_hints(&ctx, &mut app);
        batch_rename_complete_hint(&ctx, &mut app, &apply);
        assert!(!app.batch_rename_dialog.jump_mode_has_pending_confirmation());
        assert!(app.batch_rename_dialog.pending_intent().is_none());
        assert_eq!(std::fs::read(root.join("alpha.txt")).unwrap(), original);

        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(app.batch_rename_dialog.jump_mode_has_pending_confirmation());
        assert!(app.batch_rename_dialog.pending_intent().is_some());
        assert_eq!(std::fs::read(root.join("alpha.txt")).unwrap(), original);
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![egui::Event::Key {
                key: egui::Key::Enter,
                physical_key: None,
                pressed: true,
                repeat: true,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        assert!(app.batch_rename_dialog.jump_mode_has_pending_confirmation());
        assert!(app.batch_rename_dialog.pending_intent().is_some());
        assert!(!app.batch_rename_runtime_snapshot().operation_active);
        assert!(app.test_activation_trace.is_empty());
        assert_eq!(std::fs::read(root.join("alpha.txt")).unwrap(), original);
        let pending_targets = app.jump_mode_ui.retained_registry().targets();
        assert!(pending_targets.iter().all(|target| {
            matches!(
                target.id().surface(),
                SurfaceId::Popup { kind, .. } if kind == "batch-rename-apply-confirmation"
            )
        }));
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        batch_rename_test_frame(&ctx, &mut app, Vec::new());

        let (confirmation_instance, kind) = app
            .batch_rename_dialog
            .jump_mode_pending_confirmation_identity()
            .expect("the Apply child has a live per-open identity");
        assert_eq!(
            kind,
            crate::gui::jump_mode::ui::BatchRenameConfirmationKind::Apply
        );
        let parent_instance = app
            .jump_mode_ui
            .dialog_instance(crate::gui::jump_mode::ui::NavigationDialogKind::BatchRename)
            .unwrap();
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::BatchRenameConfirmation {
                parent_instance,
                confirmation_instance,
                kind,
            }
        );
        let expected_surface = SurfaceId::popup(
            kind.surface_kind(),
            confirmation_instance,
            SurfaceId::dialog("batch-rename", parent_instance),
        );
        let targets = app.jump_mode_ui.retained_registry().targets();
        assert!(
            targets
                .iter()
                .any(|target| target.metadata().label() == "Cancel batch rename")
        );
        assert!(
            targets
                .iter()
                .all(|target| target.id().surface() == &expected_surface)
        );
        assert!(targets.iter().all(|target| {
            !target.metadata().label().contains("alpha.txt")
                && !target.metadata().label().contains("fixture-")
        }));
        assert!(app.test_activation_trace.is_empty());

        let cancel = batch_rename_target_by_label(&app, "Cancel batch rename");
        batch_rename_start_hints(&ctx, &mut app);
        batch_rename_complete_hint(&ctx, &mut app, &cancel);
        assert!(app.batch_rename_dialog.jump_mode_has_pending_confirmation());
        assert!(ctx.memory(|memory| memory.has_focus(cancel.response_id())));
        assert_eq!(std::fs::read(root.join("alpha.txt")).unwrap(), original);
        batch_rename_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(!app.batch_rename_dialog.jump_mode_has_pending_confirmation());
        assert!(app.batch_rename_dialog.pending_intent().is_none());
        assert_eq!(std::fs::read(root.join("alpha.txt")).unwrap(), original);
        assert!(!app.batch_rename_runtime_snapshot().operation_active);
        app.shutdown_batch_rename_scanner();
        drop(root_guard);
        drop(workspace);
    }

    #[test]
    fn jump_mode_batch_rename_form_focuses_and_reorders_stable_rule_controls() {
        use crate::gui::jump_mode::ui::{NavigationDialogKind, NavigationOwner};

        fn frame(ctx: &egui::Context, app: &mut LauncherApp, events: Vec<egui::Event>) {
            let output = app.run_root_frame_for_test(
                ctx,
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1440.0, 1100.0),
                    )),
                    events,
                    ..actual_query_input(true)
                },
                false,
            );
            output.0.drop_without_applying_deltas();
        }

        fn target_by_label(
            app: &LauncherApp,
            label: &str,
        ) -> crate::gui::jump_mode::ui::RegisteredTarget {
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .find(|target| target.metadata().label() == label)
                .unwrap_or_else(|| panic!("missing current Batch Rename target: {label}"))
                .clone()
        }

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.set_jump_mode_enabled(true);
        app.batch_rename_dialog.open = true;
        prepare_actual_query_frame(&ctx, &mut app);
        for _ in 0..3 {
            frame(&ctx, &mut app, Vec::new());
        }
        let instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::BatchRename)
            .expect("the actual Batch Renamer has a live observed instance");
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::BatchRename,
                instance,
            }
        );
        let labels = app
            .jump_mode_ui
            .retained_registry()
            .metadata()
            .map(|metadata| metadata.label())
            .collect::<HashSet<_>>();
        for label in [
            "Choose root folder",
            "Include subfolders",
            "Extension policy",
            "New rule type",
            "Add rule",
            "Close Batch Renamer",
        ] {
            assert!(
                labels.contains(label),
                "missing enabled planning target {label}"
            );
        }
        for label in [
            "Rescan files",
            "Preview rename plan",
            "Select visible files",
        ] {
            assert!(
                !labels.contains(label),
                "disabled actions must not be offered as hints: {label}"
            );
        }

        frame(
            &ctx,
            &mut app,
            vec![
                key_press(egui::Key::Space, egui::Modifiers::SHIFT),
                egui::Event::Text(" ".into()),
            ],
        );
        let add_rule = target_by_label(&app, "Add rule");
        let hint = app
            .jump_mode_ui
            .active_session()
            .expect("leader starts a Jump session")
            .hint_map()
            .hint_for(add_rule.id())
            .expect("the live Add rule button is targetable")
            .as_str()
            .to_owned();
        frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Space, egui::Modifiers::SHIFT)],
        );
        frame(&ctx, &mut app, vec![egui::Event::Text(hint)]);
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(
            !app.jump_mode_ui
                .retained_registry()
                .metadata()
                .any(|metadata| metadata.label() == "Prefix text"),
            "hint completion focuses Add rule but does not create a rule"
        );
        assert!(ctx.memory(|memory| memory.has_focus(add_rule.response_id())));
        assert!(app.test_activation_trace.is_empty());

        frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        let first_prefix = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == "Prefix text")
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(first_prefix.len(), 1, "a fresh Enter creates one rule");
        frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        let mut before = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == "Prefix text")
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(before.len(), 2, "the second fresh Enter adds one more rule");
        before.sort_by_key(|target| target.metadata().visual_order());
        let before_ids = before
            .iter()
            .map(|target| (target.id().clone(), target.response_id()))
            .collect::<HashMap<_, _>>();

        let move_up = target_by_label(&app, "Move rule earlier");
        let position = move_up.clipped_rect().center();
        assert_eq!(
            ctx.layer_id_at(position),
            Some(NavigationDialogKind::BatchRename.layer_id().unwrap()),
            "the enabled rule reorder response is visibly clickable"
        );
        frame(
            &ctx,
            &mut app,
            vec![
                egui::Event::PointerMoved(position),
                egui::Event::PointerButton {
                    pos: position,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::NONE,
                },
            ],
        );
        frame(
            &ctx,
            &mut app,
            vec![egui::Event::PointerButton {
                pos: position,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        frame(&ctx, &mut app, Vec::new());
        let mut after = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == "Prefix text")
            .cloned()
            .collect::<Vec<_>>();
        after.sort_by_key(|target| target.metadata().visual_order());
        assert_eq!(
            after[0].id(),
            before[1].id(),
            "the second stable rule moved first"
        );
        assert_eq!(
            after[1].id(),
            before[0].id(),
            "the first stable rule moved second"
        );
        for target in &after {
            assert_eq!(
                target.response_id(),
                before_ids[target.id()],
                "native rule field identity follows RuleDraft.id through reorder"
            );
        }
        assert!(app.test_activation_trace.is_empty());
        drop(workspace);
    }

    #[test]
    fn jump_mode_batch_rename_form_uses_exact_extension_combo_popup_targets() {
        use crate::gui::jump_mode::SurfaceId;
        use crate::gui::jump_mode::ui::{NavigationDialogKind, NavigationOwner};

        fn frame(ctx: &egui::Context, app: &mut LauncherApp, events: Vec<egui::Event>) {
            let output = app.run_root_frame_for_test(
                ctx,
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1200.0, 900.0),
                    )),
                    events,
                    ..actual_query_input(true)
                },
                false,
            );
            output.0.drop_without_applying_deltas();
        }

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.set_jump_mode_enabled(true);
        app.batch_rename_dialog.open = true;
        prepare_actual_query_frame(&ctx, &mut app);
        for _ in 0..3 {
            frame(&ctx, &mut app, Vec::new());
        }
        let instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::BatchRename)
            .expect("the actual Batch Renamer has a live observed instance");
        let anchor = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == "Extension policy")
            .expect("extension policy anchor is rendered")
            .clone();
        frame(
            &ctx,
            &mut app,
            vec![
                key_press(egui::Key::Space, egui::Modifiers::SHIFT),
                egui::Event::Text(" ".into()),
            ],
        );
        let hint = app
            .jump_mode_ui
            .active_session()
            .expect("leader starts a Jump session")
            .hint_map()
            .hint_for(anchor.id())
            .expect("extension policy receives an anchor hint")
            .as_str()
            .to_owned();
        frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Space, egui::Modifiers::SHIFT)],
        );
        frame(&ctx, &mut app, vec![egui::Event::Text(hint)]);
        assert!(app.jump_mode_ui.active_session().is_none());
        assert!(
            !egui::Popup::is_any_open(&ctx),
            "hint completion does not open the combo"
        );
        assert!(ctx.memory(|memory| memory.has_focus(anchor.response_id())));

        frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(
            egui::Popup::is_any_open(&ctx),
            "fresh Enter opens the native combo"
        );
        frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::BatchRename,
                instance,
            }
        );
        let targets = app.jump_mode_ui.retained_registry().targets();
        assert!(
            targets.iter().all(|target| matches!(
                target.id().surface(),
                SurfaceId::Popup { kind, owner, .. }
                    if kind.starts_with("combo:")
                        && matches!(owner.as_ref(), SurfaceId::Dialog { kind, instance: owner_instance }
                            if kind == "batch-rename" && *owner_instance == instance)
            )),
            "only the exact Batch Rename combo popup owns targets"
        );
        assert!(
            targets
                .iter()
                .any(|target| target.metadata().label() == "Protect extension")
        );
        assert!(
            targets
                .iter()
                .any(|target| target.metadata().label() == "Edit full filename")
        );
        assert!(
            targets
                .iter()
                .all(|target| target.metadata().label() != "Add rule")
        );
        drop(workspace);
    }

    fn search_replace_test_frame(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        events: Vec<egui::Event>,
    ) {
        let output = app.run_root_frame_for_test(
            ctx,
            egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1440.0, 1100.0),
                )),
                focused: true,
                events,
                ..Default::default()
            },
            false,
        );
        output.0.drop_without_applying_deltas();
    }

    fn start_search_replace_hints(ctx: &egui::Context, app: &mut LauncherApp) {
        search_replace_test_frame(
            ctx,
            app,
            vec![
                key_press(egui::Key::Space, egui::Modifiers::SHIFT),
                egui::Event::Text(" ".into()),
            ],
        );
        assert!(app.jump_mode_ui.active_session().is_some());
        search_replace_test_frame(
            ctx,
            app,
            vec![key_release(egui::Key::Space, egui::Modifiers::SHIFT)],
        );
    }

    fn complete_search_replace_hint(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        target: &crate::gui::jump_mode::ui::RegisteredTarget,
    ) {
        let hint = app
            .jump_mode_ui
            .active_session()
            .expect("the current Jump session remains active")
            .hint_map()
            .hint_for(target.id())
            .expect("the current target receives a hint")
            .as_str()
            .to_owned();
        search_replace_test_frame(ctx, app, vec![egui::Event::Text(hint)]);
    }

    fn search_replace_target_by_label(
        app: &LauncherApp,
        label: &str,
    ) -> crate::gui::jump_mode::ui::RegisteredTarget {
        app.jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .find(|target| target.metadata().label() == label)
            .unwrap_or_else(|| panic!("missing current Search & Replace target: {label}"))
            .clone()
    }

    #[test]
    fn jump_mode_replace_approvals_focus_only_then_open_an_exclusive_cancel_child() {
        use crate::gui::jump_mode::{
            SurfaceId, TargetKind,
            ui::{NavigationDialogKind, NavigationOwner},
        };

        let ctx = egui::Context::default();
        ctx.all_styles_mut(|style| style.animation_time = 0.0);
        let repository_root = std::env::current_dir().expect("read repository root");
        let scan_parent = repository_root.join("target/productivity_expansion");
        std::fs::create_dir_all(&scan_parent).expect("create native search fixture parent");
        let root_guard = tempfile::Builder::new()
            .prefix("search_replace_jump_")
            .tempdir_in(&scan_parent)
            .expect("create disposable search root");
        let root = root_guard.path().to_path_buf();
        let source_path = root.join("fixture.txt");
        let original = "before needle猫 after\n".as_bytes().to_vec();
        std::fs::write(&source_path, &original).expect("write harmless generated source");

        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.set_jump_mode_enabled(true);
        prepare_actual_query_frame(&ctx, &mut app);
        let original_root_query = app.query.clone();
        app.search_replace_dialog.open();
        app.handle_search_replace_ui_command(crate::gui::SearchReplaceUiCommand::SelectRoot(
            root.clone(),
        ));
        for _ in 0..3 {
            search_replace_test_frame(&ctx, &mut app, Vec::new());
        }

        let instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::SearchReplace)
            .expect("the actual Search & Replace Window has a live instance");
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::SearchReplace,
                instance,
            }
        );
        let pattern_mode = search_replace_target_by_label(&app, "Search pattern mode");
        assert_eq!(pattern_mode.metadata().kind(), TargetKind::ComboBox);
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &pattern_mode);
        assert!(
            !egui::Popup::is_any_open(&ctx),
            "hint focus does not open the combo"
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(
            egui::Popup::is_any_open(&ctx),
            "fresh Enter opens native options"
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());
        let popup_targets = app.jump_mode_ui.retained_registry().targets();
        assert!(!popup_targets.is_empty());
        assert!(popup_targets.iter().all(|target| matches!(
            target.id().surface(),
            SurfaceId::Popup { kind, owner, .. }
                if kind.starts_with("combo:")
                    && matches!(owner.as_ref(), SurfaceId::Dialog { kind, instance: owner_instance }
                        if kind == "search-replace" && *owner_instance == instance)
        )), "only the exact Search & Replace combo options own popup targets");
        assert!(
            popup_targets
                .iter()
                .any(|target| target.metadata().label() == "Rust regex")
        );
        assert!(
            popup_targets
                .iter()
                .all(|target| target.metadata().label() != "Search")
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Escape, egui::Modifiers::NONE)],
        );
        assert!(!egui::Popup::is_any_open(&ctx));
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let pattern = search_replace_target_by_label(&app, "Search pattern");
        assert_eq!(pattern.metadata().kind(), TargetKind::TextEntry);
        assert_eq!(
            pattern.id().surface(),
            &SurfaceId::dialog("search-replace", instance)
        );

        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &pattern);
        assert_eq!(app.search_replace_dialog.test_pattern(), "");
        assert_eq!(app.query, original_root_query);
        assert!(!app.search_replace_dialog.test_search_ticket_active());
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(pattern.response_id()),
            "hint completion focuses the actual pattern editor"
        );

        search_replace_test_frame(&ctx, &mut app, vec![egui::Event::Text("needle猫".into())]);
        assert_eq!(app.search_replace_dialog.test_pattern(), "needle猫");
        assert_eq!(
            app.query, original_root_query,
            "form typing stays out of Root"
        );
        assert!(!app.search_replace_dialog.test_search_ticket_active());
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(pattern.response_id()),
            "Unicode typing retains native caret ownership"
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let search = search_replace_target_by_label(&app, "Search");
        assert_eq!(search.metadata().kind(), TargetKind::Button);
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &search);
        assert!(!app.search_replace_dialog.test_search_ticket_active());
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(search.response_id()),
            "hint completion focuses Search without starting work"
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(app.search_replace_dialog.test_search_ticket_active());

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let result_counts = loop {
            app.poll_search_replace_runtime(&ctx);
            if let Some(counts) = app.search_replace_dialog.test_result_counts() {
                break counts;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the generated read-only search should be accepted by the current generation"
            );
            thread::sleep(Duration::from_millis(10));
        };
        assert_eq!(result_counts.1, 1, "the fixture has one matching file");
        assert_eq!(result_counts.2, 1, "the fixture has one matching span");
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        // Accepting the asynchronous search result changes the dependent
        // target set. Collect one stable frame before starting a new hint
        // session against that current view.
        search_replace_test_frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::SearchReplace,
                instance,
            }
        );

        let settings = search_replace_target_by_label(&app, "Search and Replace settings");
        assert!(settings.enabled() && settings.clipped_rect().is_positive());
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &settings);
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let file_target = search_replace_target_by_label(&app, "Inspect file result");
        assert_eq!(file_target.metadata().kind(), TargetKind::Action);
        assert!(file_target.enabled());
        assert!(file_target.clipped_rect().width() > 0.0);
        let semantic_id = format!("{:?}", file_target.id());
        assert!(!semantic_id.contains("fixture.txt"));
        assert!(!semantic_id.contains(root.to_string_lossy().as_ref()));
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &file_target);
        assert_eq!(
            app.search_replace_dialog
                .test_selected_file()
                .map(std::fs::canonicalize)
                .transpose()
                .unwrap(),
            Some(std::fs::canonicalize(&source_path).unwrap())
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(file_target.response_id()),
            "Select focuses the exact current file inspection response"
        );
        assert_eq!(app.search_replace_dialog.test_approved_match_count(), 0);
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let match_target = search_replace_target_by_label(&app, "Inspect match");
        assert_eq!(match_target.metadata().kind(), TargetKind::Action);
        assert_eq!(match_target.id().surface(), file_target.id().surface());
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &match_target);
        assert!(app.search_replace_dialog.test_inspected_match().is_some());
        assert_eq!(app.search_replace_dialog.test_approved_match_count(), 0);
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        assert!(app.test_activation_trace.is_empty());

        let approval = search_replace_target_by_label(&app, "Approve match");
        assert_eq!(approval.metadata().kind(), TargetKind::Checkbox);
        assert!(approval.enabled());
        let approval_semantic = format!("{:?}", approval.id());
        assert!(!approval_semantic.contains("fixture.txt"));
        assert!(!approval_semantic.contains(root.to_string_lossy().as_ref()));
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &approval);
        assert_eq!(
            app.search_replace_dialog.test_approved_match_count(),
            0,
            "hint completion focuses the checkbox without approving its match"
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(approval.response_id())
        );
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Space, egui::Modifiers::NONE)],
        );
        assert_eq!(app.search_replace_dialog.test_approved_match_count(), 1);
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Space, egui::Modifiers::NONE)],
        );

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let review_apply = loop {
            app.poll_search_replace_runtime(&ctx);
            search_replace_test_frame(&ctx, &mut app, Vec::new());
            if let Some(target) = app
                .jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .find(|target| {
                    target.metadata().label() == "Review Apply"
                        && target.enabled()
                        && target.clipped_rect().is_positive()
                })
                .cloned()
            {
                break target;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the one approved generated match should publish a current Review Apply target"
            );
            thread::sleep(Duration::from_millis(10));
        };
        let original_generation = app
            .search_replace_dialog
            .test_result_counts()
            .expect("the generated search result remains current")
            .0;
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &review_apply);
        assert!(!app.search_replace_dialog.test_apply_confirmation_open());
        assert_eq!(
            std::fs::read(&source_path).unwrap(),
            original,
            "Review Apply hint completion does not open confirmation or write"
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(app.search_replace_dialog.test_apply_confirmation_open());
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        assert!(
            app.jump_mode_ui.retained_registry().targets().is_empty(),
            "opening the child retires already collected parent actions"
        );
        assert!(!app.search_replace_dialog.test_apply_confirmation_pending());
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![egui::Event::Key {
                key: egui::Key::Enter,
                physical_key: None,
                pressed: true,
                repeat: true,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        assert!(app.search_replace_dialog.test_apply_confirmation_open());
        assert!(!app.search_replace_dialog.test_apply_confirmation_pending());
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let (confirmation_instance, confirmation_kind, _) = app
            .search_replace_dialog
            .jump_mode_confirmation_identity()
            .map(|identity| {
                (
                    identity.confirmation_instance,
                    identity.kind,
                    identity.subject,
                )
            })
            .expect("the exact frozen Apply confirmation is current");
        assert_eq!(
            confirmation_kind,
            crate::gui::jump_mode::ui::SearchReplaceConfirmationKind::Apply
        );
        let child_cancel = search_replace_target_by_label(&app, "Cancel");
        let child_surface = SurfaceId::popup(
            confirmation_kind.surface_kind(),
            confirmation_instance,
            SurfaceId::dialog("search-replace", instance),
        );
        assert_eq!(child_cancel.id().surface(), &child_surface);
        let normal_cancel_id = child_cancel.id().clone();
        let normal_cancel_response = child_cancel.response_id();
        let confirm_target = search_replace_target_by_label(&app, "Confirm and Apply");
        assert_eq!(confirm_target.metadata().kind(), TargetKind::Button);
        let confirm_response = confirm_target.response_id();
        assert!(
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .all(|target| { target.id().surface() == &child_surface }),
            "the child confirmation owns targets exclusively"
        );
        assert_eq!(
            app.search_replace_dialog.test_result_counts().unwrap().0,
            original_generation
        );

        app.search_replace_dialog
            .test_mark_apply_confirmation_pending();
        search_replace_test_frame(&ctx, &mut app, Vec::new());
        let pending_cancel = search_replace_target_by_label(&app, "Cancel before submission");
        assert_eq!(pending_cancel.id().surface(), &child_surface);
        assert_ne!(
            pending_cancel.id(),
            &normal_cancel_id,
            "pending Cancel has distinct semantic authority from the normal child Cancel"
        );
        assert_ne!(
            pending_cancel.response_id(),
            normal_cancel_response,
            "the pending phase cannot inherit a focused native response ID"
        );
        assert_ne!(
            pending_cancel.response_id(),
            confirm_response,
            "pending Cancel cannot inherit the normal Confirm response ID"
        );
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &pending_cancel);
        assert!(app.search_replace_dialog.test_apply_confirmation_pending());
        assert_eq!(std::fs::read(&source_path).unwrap(), original);
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(!app.search_replace_dialog.test_apply_confirmation_open());
        assert!(!app.search_replace_dialog.test_apply_confirmation_pending());
        assert_eq!(std::fs::read(&source_path).unwrap(), original);

        app.shutdown_search_replace_runtime();
        drop(root_guard);
        drop(workspace);
    }

    #[test]
    fn jump_mode_replace_approvals_recovery_receipt_headers_are_real_nested_targets() {
        use crate::gui::jump_mode::ui::{
            NavigationDialogKind, NavigationOwner, SearchReplaceConfirmationKind,
        };
        use crate::gui::jump_mode::{SurfaceId, TargetKind};

        let ctx = egui::Context::default();
        ctx.all_styles_mut(|style| style.animation_time = 0.0);
        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.set_jump_mode_enabled(true);
        prepare_actual_query_frame(&ctx, &mut app);
        app.search_replace_dialog.open();
        for (id, status) in [
            ("generated-recovery", "recovery_required"),
            ("generated-applied", "applied"),
        ] {
            let receipt = serde_json::from_value(serde_json::json!({
                "id": id,
                "search_revision": 1,
                "search_generation": 1,
                "replacement_revision": 1,
                "status": status,
                "entries": [],
                "message": "Generated fixture receipt"
            }))
            .expect("the fixture receipt uses the durable receipt schema");
            app.search_replace_dialog.test_push_receipt(receipt);
        }
        for _ in 0..3 {
            search_replace_test_frame(&ctx, &mut app, Vec::new());
        }
        let instance = app
            .jump_mode_ui
            .dialog_instance(NavigationDialogKind::SearchReplace)
            .expect("the Search & Replace owner is live");
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::SearchReplace,
                instance,
            }
        );
        let outer =
            search_replace_target_by_label(&app, "Replacement receipts, Restore, and Recovery");
        assert_eq!(outer.metadata().kind(), TargetKind::Button);
        assert_eq!(
            outer.id().surface(),
            &SurfaceId::dialog("search-replace", instance)
        );
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &outer);
        assert!(!app.search_replace_dialog.test_reveal_receipts());
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(outer.response_id())
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let receipt_headers = app
            .jump_mode_ui
            .retained_registry()
            .targets()
            .iter()
            .filter(|target| target.metadata().label() == "Receipt details")
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(receipt_headers.len(), 2);
        assert!(
            receipt_headers
                .iter()
                .all(|target| target.id().surface()
                    == &SurfaceId::dialog("search-replace", instance))
        );
        assert_ne!(receipt_headers[0].id(), receipt_headers[1].id());
        for target in &receipt_headers {
            let crate::gui::jump_mode::SemanticTargetId::Named(identity) = target.id().semantic()
            else {
                panic!("receipt header identities use an opaque named target");
            };
            assert!(!identity.contains("generated-applied"));
            assert!(!identity.contains("generated-recovery"));
        }
        // Receipt rows render newest first, and the applied receipt was
        // inserted last. Choose by real visual order; receipt payloads stay
        // opaque to Jump metadata and test routing alike.
        let applied_header = receipt_headers
            .iter()
            .min_by_key(|target| target.metadata().visual_order())
            .expect("the newest generated receipt header is visible")
            .clone();
        assert_eq!(applied_header.metadata().label(), "Receipt details");

        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &applied_header);
        assert!(
            app.search_replace_dialog
                .jump_mode_confirmation_identity()
                .is_none(),
            "selecting a receipt header never opens a Restore confirmation"
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(applied_header.response_id())
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let restore = search_replace_target_by_label(&app, "Restore receipt");
        assert_eq!(restore.metadata().kind(), TargetKind::Button);
        assert_eq!(
            restore.id().surface(),
            &SurfaceId::dialog("search-replace", instance)
        );
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &restore);
        assert!(
            app.search_replace_dialog
                .jump_mode_confirmation_identity()
                .is_none(),
            "selecting Restore only focuses the receipt action"
        );
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(restore.response_id())
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert_eq!(
            app.search_replace_dialog
                .jump_mode_confirmation_identity()
                .map(|identity| identity.kind),
            Some(SearchReplaceConfirmationKind::Restore),
            "only a distinct later Enter opens the exact Restore child"
        );
        assert!(
            app.jump_mode_ui.retained_registry().targets().is_empty(),
            "opening Restore immediately retires parent receipt actions"
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        search_replace_test_frame(&ctx, &mut app, Vec::new());

        let identity = app
            .search_replace_dialog
            .jump_mode_confirmation_identity()
            .expect("the exact Restore confirmation remains current");
        assert_eq!(identity.kind, SearchReplaceConfirmationKind::Restore);
        let child_surface = SurfaceId::popup(
            SearchReplaceConfirmationKind::Restore.surface_kind(),
            identity.confirmation_instance,
            SurfaceId::dialog("search-replace", instance),
        );
        let child_cancel = search_replace_target_by_label(&app, "Cancel");
        assert_eq!(child_cancel.id().surface(), &child_surface);
        assert!(
            app.jump_mode_ui
                .retained_registry()
                .targets()
                .iter()
                .all(|target| { target.id().surface() == &child_surface }),
            "the exact Restore child owns its Cancel control exclusively"
        );
        start_search_replace_hints(&ctx, &mut app);
        complete_search_replace_hint(&ctx, &mut app, &child_cancel);
        assert!(
            app.search_replace_dialog
                .jump_mode_confirmation_identity()
                .is_some()
        );
        search_replace_test_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(
            app.search_replace_dialog
                .jump_mode_confirmation_identity()
                .is_none()
        );

        app.shutdown_search_replace_runtime();
        drop(workspace);
    }

    #[test]
    fn actual_root_navigation_owner_follows_expanded_dialogs() {
        use crate::gui::jump_mode::ui::{NavigationDialogKind, NavigationOwner, settings_layer_id};

        fn render_dialog_layers(
            ctx: &egui::Context,
            file_search: bool,
            snippets: bool,
            settings: bool,
            unknown: bool,
            foreground: Option<egui::LayerId>,
        ) {
            ctx.run_ui(actual_query_input(true), |ui| {
                if file_search {
                    egui::Window::new("File Search").show(ui.ctx(), |_| {});
                }
                if snippets {
                    egui::Window::new("Snippets").show(ui.ctx(), |_| {});
                }
                if settings {
                    egui::Window::new("Settings").show(ui.ctx(), |_| {});
                }
                if unknown {
                    egui::Window::new("Unsupported modal").show(ui.ctx(), |_| {});
                }
                if let Some(layer) = foreground {
                    ui.ctx().move_to_top(layer);
                }
            })
            .drop_without_applying_deltas();
        }

        fn route_owner(ctx: &egui::Context, app: &mut LauncherApp) -> NavigationOwner {
            app.jump_mode_ui.begin_frame();
            let (candidate, visibility_changed, combo_popup) =
                app.jump_mode_navigation_owner_candidate(ctx, true);
            app.jump_mode_ui.update_navigation_owner_with_combo_popup(
                ctx,
                candidate,
                visibility_changed,
                combo_popup,
            )
        }

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        assert_eq!(route_owner(&ctx, &mut app), NavigationOwner::Root);

        app.file_search_dialog.open = true;
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Blocked,
            "an open dialog without a completed visible layer cannot fall back to Root"
        );
        render_dialog_layers(&ctx, true, false, false, false, None);
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Blocked,
            "the first observed File Search owner transition consumes the frame"
        );
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::FileSearch,
                instance: 1
            }
        );

        app.snippet_dialog.open = true;
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Blocked,
            "opening another supported dialog invalidates the prior scope"
        );
        let snippets_layer =
            egui::LayerId::new(egui::Order::Middle, egui::Id::new(Some("Snippets")));
        render_dialog_layers(&ctx, true, true, false, false, Some(snippets_layer));
        assert_eq!(route_owner(&ctx, &mut app), NavigationOwner::Blocked);
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Dialog {
                kind: NavigationDialogKind::Snippets,
                instance: 1
            },
            "the actual foreground Snippets layer takes ownership after a fresh frame"
        );

        app.show_settings = true;
        assert_eq!(route_owner(&ctx, &mut app), NavigationOwner::Blocked);
        render_dialog_layers(&ctx, true, true, true, false, Some(settings_layer_id()));
        assert_eq!(route_owner(&ctx, &mut app), NavigationOwner::Blocked);
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Settings { instance: 1 },
            "Settings retains its existing owner semantics above expanded dialogs"
        );

        let unknown_layer = egui::LayerId::new(
            egui::Order::Middle,
            egui::Id::new(Some("Unsupported modal")),
        );
        render_dialog_layers(&ctx, true, true, true, true, Some(unknown_layer));
        assert_eq!(
            route_owner(&ctx, &mut app),
            NavigationOwner::Blocked,
            "an unknown top window blocks all supported owners behind it"
        );
        assert!(app.test_activation_trace.is_empty());
        drop(workspace);
    }

    #[test]
    fn settings_owner_blocks_root_autofocus_and_enter_activation() {
        use crate::gui::jump_mode::ui::NavigationOwner;

        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.set_jump_mode_enabled(true);
        app.test_skip_history_persistence = true;
        prepare_actual_query_frame(&ctx, &mut app);
        app.selected = Some(0);
        app.show_settings = true;
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }
        let candidate = app.jump_mode_navigation_owner_candidate(&ctx, true).0;
        let gates = (
            app.jump_mode_enabled(),
            app.visible_flag.load(Ordering::Relaxed),
            ctx.viewport_id(),
            ctx.viewport_id() == egui::ViewportId::ROOT,
            ctx.input(|input| input.focused),
            app.pin_list_open,
            app.ocr_surface_visible(),
            app.confirm_modal.is_open(),
            app.action_sheet.is_open(),
        );
        let prompt_gates = (
            app.macro_prompt.pending.is_some(),
            app.macro_parameter_prompt.owns_input(),
            app.snippet_prompt_dialog.is_open(),
            app.root_frame_logic
                .as_ref()
                .is_some_and(|logic| logic.snippet_prompt_owns_input),
            app.screen_draw_controller.toolbar_open(),
            egui::Popup::is_any_open(&ctx),
            ctx.memory(|memory| memory.top_modal_layer().is_some()),
        );
        let top_layer = crate::gui::jump_mode::ui::visible_top_middle_layer(&ctx);
        let top_is_settings = top_layer == Some(crate::gui::jump_mode::ui::settings_layer_id());
        let resolver_facts = (
            ctx.viewport_id(),
            ctx.input(|input| input.focused),
            egui::Popup::is_any_open(&ctx),
            ctx.memory(|memory| memory.top_modal_layer()),
            top_layer,
            top_is_settings,
            crate::gui::jump_mode::ui::focused_response_layer(&ctx),
            app.show_settings,
            app.jump_mode_ui.settings_instance(),
            app.pin_list_open,
            app.ocr_surface_visible(),
            app.screen_draw_controller.toolbar_open(),
        );
        assert_eq!(
            app.jump_mode_ui.frame_navigation_owner(),
            NavigationOwner::Settings { instance: 1 },
            "candidate={candidate:?}, direct={:?}, resolver_facts={resolver_facts:?}, gates={gates:?}, prompts={prompt_gates:?}",
            crate::gui::jump_mode::ui::resolve_layer_navigation_owner(
                &ctx,
                crate::gui::jump_mode::ui::NavigationWindows {
                    settings: app
                        .show_settings
                        .then_some(app.jump_mode_ui.settings_instance()),
                    notes: None,
                    todo: None,
                    timer: None,
                    paste_sequence: None,
                    mkmacro: None,
                    dialogs: [None; crate::gui::jump_mode::ui::NavigationDialogKind::ALL.len()],
                }
            ),
        );
        assert!(!ctx.memory(|memory| memory.has_focus(egui::Id::new("query_input"))));

        let query_before = app.query.clone();
        app.focus_query = true;
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();

        assert_eq!(
            app.query, query_before,
            "Settings prevents root query edits"
        );
        assert_eq!(app.selected, Some(0));
        assert!(app.focus_query, "background autofocus remains pending");
        assert!(!ctx.memory(|memory| memory.has_focus(egui::Id::new("query_input"))));
        assert!(
            app.test_activation_trace.is_empty(),
            "Enter cannot activate a root result"
        );
        drop(workspace);
    }

    #[test]
    fn settings_search_navigation_escape_dismisses_results_before_closing_settings() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.test_skip_history_persistence = true;
        let release_escape = |app: &mut LauncherApp| {
            app.run_root_frame_for_test(
                &ctx,
                egui::RawInput {
                    events: vec![key_release(egui::Key::Escape, egui::Modifiers::NONE)],
                    ..actual_query_input(true)
                },
                false,
            )
            .0
            .drop_without_applying_deltas();
        };
        prepare_actual_query_frame(&ctx, &mut app);
        app.show_settings = true;
        app.settings_editor.fuzzy_weight = 2.25;
        for _ in 0..2 {
            app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
                .0
                .drop_without_applying_deltas();
        }

        let (query_id, _) = app
            .settings_editor
            .test_search_query_response
            .expect("root rendered the real Settings search response");
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(query_id));
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text("fuzzy weight".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert_eq!(app.settings_editor.settings_search_query, "fuzzy weight");
        assert!(!app.settings_editor.settings_search_match_ids.is_empty());

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        release_escape(&mut app);
        assert!(
            app.show_settings,
            "first Escape dismisses search results only; preflight={:?}; frame={}",
            app.settings_editor.test_root_escape_preflight,
            app.settings_editor
                .test_last_navigation_diagnostic
                .as_deref()
                .unwrap_or("no Settings navigation frame was recorded")
        );
        assert!(app.settings_editor.settings_search_query.is_empty());
        assert_eq!(app.settings_editor.fuzzy_weight, 2.25);

        ctx.memory_mut(|memory| memory.request_focus(query_id));
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text("fuzzy weight".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        let settings_owner = app.settings_navigation_owner_instance();
        ctx.memory_mut(|memory| memory.request_focus(egui::Id::new("query_input")));
        assert!(
            !app.settings_editor
                .handle_search_escape_before_container_close(&ctx, settings_owner),
            "a current root-query focus cannot fall back to stale Settings search focus"
        );
        assert_eq!(app.settings_editor.settings_search_query, "fuzzy weight");
        let result_id = app
            .settings_editor
            .test_search_result_responses
            .first()
            .map(|(_, response_id, _)| *response_id)
            .expect("the root Settings window rendered a real result button");
        ctx.memory_mut(|memory| memory.request_focus(result_id));
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(result_id));
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        release_escape(&mut app);
        assert!(
            app.show_settings,
            "Escape from the actual result response dismisses search before closing Settings; preflight={:?}; frame={}",
            app.settings_editor.test_root_escape_preflight,
            app.settings_editor
                .test_last_navigation_diagnostic
                .as_deref()
                .unwrap_or("no Settings navigation frame was recorded")
        );
        assert!(app.settings_editor.settings_search_query.is_empty());
        assert_eq!(app.settings_editor.fuzzy_weight, 2.25);

        app.set_jump_mode_enabled(true);
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![egui::Event::Text("fuzzy weight".into())],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        let jump_focus_id = app
            .settings_editor
            .test_search_result_responses
            .first()
            .map(|(_, response_id, _)| *response_id)
            .expect("the Jump priority check retains an actual search result response");
        ctx.memory_mut(|memory| memory.request_focus(jump_focus_id));
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(jump_focus_id));
        start_actual_root_jump_mode(&ctx, &mut app);
        assert!(app.jump_mode_ui.active_session().is_some());
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        assert!(app.show_settings);
        assert_eq!(
            app.settings_editor.settings_search_query, "fuzzy weight",
            "the first Escape cancels Jump Mode without dismissing Settings search"
        );
        assert!(app.jump_mode_ui.active_session().is_none());
        release_escape(&mut app);
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        app.run_root_frame_for_test(&ctx, actual_query_input(true), false)
            .0
            .drop_without_applying_deltas();
        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        release_escape(&mut app);
        assert!(app.show_settings);
        assert!(app.settings_editor.settings_search_query.is_empty());

        app.run_root_frame_for_test(
            &ctx,
            egui::RawInput {
                events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                ..actual_query_input(true)
            },
            false,
        )
        .0
        .drop_without_applying_deltas();
        release_escape(&mut app);
        assert!(
            !app.show_settings,
            "Escape with no search results keeps the container action"
        );
        drop(workspace);
    }

    #[test]
    fn settings_search_navigation_paste_open_survives_discarded_sizing_pass() {
        let ctx = egui::Context::default();
        let workspace = crate::performance::workloads::IsolatedWorkspace::new();
        let mut persisted_settings = Settings::default();
        persisted_settings.paste_sequence.next_hotkey = None;
        persisted_settings.paste_sequence.cancel_hotkey = None;
        persisted_settings
            .save(
                workspace
                    .root()
                    .join("settings.json")
                    .to_str()
                    .expect("the isolated settings path is valid UTF-8"),
            )
            .unwrap();
        let mut app = root_list_app_at(&ctx, two_results(), workspace.root());
        prepare_actual_query_frame(&ctx, &mut app);
        app.open_paste_sequence_settings_dialog();
        assert_eq!(
            app.settings_editor
                .pending_settings_navigation
                .as_ref()
                .map(|pending| pending.control_id.as_str()),
            Some("paste.next.enabled")
        );

        let mut target_response_id = None;
        for frame in 0..6 {
            let (output, passes) =
                app.run_root_frame_for_test(&ctx, actual_query_input(true), frame == 0);
            output.drop_without_applying_deltas();
            if frame == 0 {
                assert!(passes >= 2, "the first Settings window pass was discarded");
            }
            if let Some((id, response_id)) = app.settings_editor.test_last_navigation_focus.as_ref()
                && id == "paste.next.enabled"
                && ctx.memory(|memory| memory.focused()) == Some(*response_id)
            {
                target_response_id = Some(*response_id);
                break;
            }
        }
        let target_response_id = target_response_id.unwrap_or_else(|| {
            panic!(
                "a later visible Settings pass binds the real Paste checkbox response; {}",
                app.settings_editor
                    .test_last_navigation_diagnostic
                    .as_deref()
                    .unwrap_or("no Settings navigation frame was recorded")
            )
        });
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(target_response_id)
        );
        assert!(app.settings_editor.pending_settings_navigation.is_none());
        assert!(!app.settings_editor.paste_next_enabled);
        drop(workspace);
    }

    fn settings_cross_owner_input(events: Vec<egui::Event>) -> egui::RawInput {
        egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(1600.0, 1200.0),
            )),
            focused: true,
            events,
            ..Default::default()
        }
    }

    fn run_settings_cross_owner_frame(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        events: Vec<egui::Event>,
    ) -> usize {
        let (output, passes) =
            app.run_root_frame_for_test(ctx, settings_cross_owner_input(events), false);
        output.drop_without_applying_deltas();
        passes
    }

    fn cross_owner_test_settings() -> Settings {
        let mut settings = Settings::default();
        settings.paste_sequence.next_hotkey = None;
        settings.paste_sequence.cancel_hotkey = None;
        settings
    }

    fn persist_cross_owner_test_settings(path: &str) -> Vec<u8> {
        let bytes = serde_json::to_vec(&cross_owner_test_settings()).unwrap();
        std::fs::write(path, &bytes).unwrap();
        bytes
    }

    fn prepare_settings_cross_owner_root(ctx: &egui::Context, app: &mut LauncherApp) {
        app.visible_flag.store(true, Ordering::SeqCst);
        app.restore_flag.store(false, Ordering::SeqCst);
        app.last_visible = true;
        app.focus_query = false;
        app.follow_mouse = false;
        focus_launcher_query(ctx, app);
        run_settings_cross_owner_frame(ctx, app, Vec::new());
    }

    fn queue_settings_cross_owner_destination(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        query: &str,
        control_id: &str,
    ) -> egui::Id {
        app.show_settings = true;
        app.settings_editor.settings_search_query = query.to_owned();
        app.settings_editor.settings_search_selected_id = Some(control_id.to_owned());
        for _ in 0..3 {
            run_settings_cross_owner_frame(ctx, app, Vec::new());
        }
        assert!(
            app.settings_editor
                .test_search_result_responses
                .iter()
                .any(|(id, _, _)| id == control_id),
            "the real Settings search renders {control_id}"
        );
        let (query_id, _) = app
            .settings_editor
            .test_search_query_response
            .expect("the real Settings search query response is rendered");
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(query_id));
        run_settings_cross_owner_frame(
            ctx,
            app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        query_id
    }

    fn open_settings_cross_owner_destination(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        query: &str,
        control_id: &str,
    ) -> egui::Id {
        let query_id = queue_settings_cross_owner_destination(ctx, app, query, control_id);
        run_settings_cross_owner_frame(
            ctx,
            app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        query_id
    }

    fn wait_for_settings_cross_owner_focus(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        control_id: &str,
    ) -> Option<egui::Id> {
        for _ in 0..8 {
            if let Some((id, response_id)) = app.settings_editor.test_last_navigation_focus.as_ref()
                && id == control_id
                && ctx.memory(|memory| memory.focused()) == Some(*response_id)
            {
                return Some(*response_id);
            }
            if let Some((id, response_id)) = app
                .settings_editor
                .test_last_dedicated_navigation_focus
                .as_ref()
                && id == control_id
                && ctx.memory(|memory| memory.focused()) == Some(*response_id)
            {
                return Some(*response_id);
            }
            run_settings_cross_owner_frame(ctx, app, Vec::new());
        }
        None
    }

    struct SettingsNavigationProbePlugin;

    impl Plugin for SettingsNavigationProbePlugin {
        fn search(&self, _query: &str) -> Vec<Action> {
            Vec::new()
        }

        fn name(&self) -> &str {
            "cross_owner_probe"
        }

        fn description(&self) -> &str {
            "Settings navigation fixture"
        }

        fn capabilities(&self) -> &[&str] {
            &["probe_capability"]
        }

        fn default_settings(&self) -> Option<serde_json::Value> {
            Some(serde_json::json!({"unchanged": true}))
        }
    }

    struct DisabledBuiltinHistoryProbePlugin {
        settings_ui_calls: Arc<AtomicUsize>,
    }

    impl Plugin for DisabledBuiltinHistoryProbePlugin {
        fn search(&self, _query: &str) -> Vec<Action> {
            Vec::new()
        }

        fn name(&self) -> &str {
            "history"
        }

        fn description(&self) -> &str {
            "Disabled built-in Settings navigation fixture"
        }

        fn capabilities(&self) -> &[&str] {
            &["probe_capability"]
        }

        fn default_settings(&self) -> Option<serde_json::Value> {
            Some(serde_json::json!({"untouched": true}))
        }

        fn settings_ui(&mut self, _ui: &mut egui::Ui, _value: &mut serde_json::Value) {
            self.settings_ui_calls.fetch_add(1, Ordering::SeqCst);
        }
    }

    #[test]
    fn settings_search_delivery_reveals_disabled_builtin_enable_without_calling_provider() {
        let ctx = egui::Context::default();
        ctx.global_style_mut(|style| style.animation_time = 0.0);
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.test_skip_history_persistence = true;
        let provider_calls = Arc::new(AtomicUsize::new(0));
        app.plugins
            .register_builtin_for_settings_test(DisabledBuiltinHistoryProbePlugin {
                settings_ui_calls: Arc::clone(&provider_calls),
            });
        app.enabled_plugins = Some(std::collections::HashSet::new());
        app.plugins
            .sync_enabled_plugins(app.enabled_plugins.as_ref());
        app.plugin_editor
            .sync_committed_settings(&cross_owner_test_settings(), app.plugins.plugin_infos());
        prepare_settings_cross_owner_root(&ctx, &mut app);

        let registration = app
            .plugins
            .settings_catalog_snapshot_if_changed(None)
            .and_then(|snapshot| {
                snapshot
                    .plugins
                    .into_iter()
                    .find(|plugin| plugin.name == "history")
            })
            .expect("the disabled fixture has one current built-in registration");
        assert_eq!(
            registration.origin,
            crate::plugin::PluginCatalogOrigin::Builtin
        );
        assert!(registration.has_settings);
        assert!(!registration.enabled);
        let requested_id = "plugin.history.max_entries".to_owned();
        let prerequisite_id = format!(
            "plugin_editor.builtin.history.{}.enabled",
            registration.epoch
        );
        let committed_settings = persist_cross_owner_test_settings(&app.settings_path);

        app.show_settings = true;
        app.settings_editor.settings_search_query = "history limit".to_owned();
        for _ in 0..3 {
            run_settings_cross_owner_frame(&ctx, &mut app, Vec::new());
        }
        let (_, history_response_id, _) = app
            .settings_editor
            .test_search_result_responses
            .iter()
            .find(|(control_id, _, _)| control_id == &requested_id)
            .cloned()
            .expect("the stabilized current results include the exact History response");
        let history_response = ctx
            .read_response(history_response_id)
            .expect("the History search result is an actual current Response");
        assert!(history_response.enabled());
        assert!(
            history_response.interact_rect.is_positive(),
            "the current History Response has a visible interactive portion"
        );
        app.settings_editor.settings_search_selected_id = Some(requested_id.clone());
        ctx.memory_mut(|memory| memory.request_focus(history_response_id));
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(history_response_id),
            "focus is assigned to the requested current History result, after catalog refresh"
        );
        run_settings_cross_owner_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        run_settings_cross_owner_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::Enter, egui::Modifiers::NONE)],
        );
        assert!(
            app.show_plugins,
            "fresh Search Enter reveals the current disabled builtin prerequisite; selected={:?} pending={:?} diagnostic={:?} history={:?}",
            app.settings_editor.settings_search_selected_id,
            app.settings_editor
                .pending_settings_navigation
                .as_ref()
                .map(|pending| (
                    pending.control_id.as_str(),
                    &pending.delivery,
                    pending.catalog_revision,
                )),
            app.settings_editor.test_last_navigation_diagnostic,
            app.settings_editor.test_search_navigation_history,
        );
        let pending_prerequisite_route = app
            .settings_editor
            .pending_settings_navigation
            .as_ref()
            .is_some_and(|pending| {
                pending.control_id == prerequisite_id
                    && matches!(
                        &pending.delivery,
                        crate::settings_editor::SettingsNavigationDelivery::BuiltinPrerequisite {
                            requested_control_id,
                        } if requested_control_id == &requested_id
                    )
            });
        let completed_prerequisite_route = app
            .settings_editor
            .settings_navigation_highlight
            .as_ref()
            .is_some_and(|highlight| {
                highlight.control_id == prerequisite_id
                    && matches!(
                        &highlight.delivery,
                        crate::settings_editor::SettingsNavigationDelivery::BuiltinPrerequisite {
                            requested_control_id,
                        } if requested_control_id == &requested_id
                    )
            });
        assert!(
            pending_prerequisite_route || completed_prerequisite_route,
            "the unavailable result is pending or completed only through its exact Enable prerequisite; pending={:?} highlight={:?}",
            app.settings_editor.pending_settings_navigation,
            app.settings_editor.settings_navigation_highlight,
        );
        let enabled_response =
            wait_for_settings_cross_owner_focus(&ctx, &mut app, &prerequisite_id)
                .expect("the real Plugin Settings checkbox receives the one-shot focus handoff");
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(enabled_response)
        );
        assert!(app.settings_editor.pending_settings_navigation.is_none());
        assert!(app.settings_editor.settings_navigation_highlight.as_ref().is_some_and(
            |highlight| {
                highlight.control_id == prerequisite_id
                    && matches!(
                        &highlight.delivery,
                        crate::settings_editor::SettingsNavigationDelivery::BuiltinPrerequisite {
                            requested_control_id,
                        } if requested_control_id == &requested_id
                    )
            }
        ));
        let history_len = app.settings_editor.test_search_navigation_history.len();
        run_settings_cross_owner_frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            ctx.memory(|memory| memory.focused()),
            Some(enabled_response)
        );
        assert_eq!(provider_calls.load(Ordering::SeqCst), 0);
        assert!(
            app.enabled_plugins
                .as_ref()
                .is_some_and(|enabled| !enabled.contains("history")),
            "revealing the prerequisite never enables the plugin"
        );
        assert_eq!(provider_calls.load(Ordering::SeqCst), 0);
        assert!(
            app.settings_editor.test_search_navigation_history[history_len..]
                .iter()
                .any(|event| {
                    event.contains(&format!("control={prerequisite_id}"))
                        && event.contains("focus_requested=false")
                }),
            "the later observer highlights the same response without requesting focus again"
        );
        assert!(!app.settings_save_pending());
        assert_eq!(
            std::fs::read(&app.settings_path).unwrap(),
            committed_settings
        );

        assert!(app.close_front_dialog());
        assert!(app.settings_editor.settings_navigation_highlight.is_none());
        assert!(app.enabled_plugins.as_ref().unwrap().is_empty());
        assert_eq!(provider_calls.load(Ordering::SeqCst), 0);
        drop(workspace);
    }

    #[test]
    fn settings_search_cross_owner_theme_waits_through_window_sizing_before_focusing_response() {
        let ctx = egui::Context::default();
        ctx.global_style_mut(|style| style.animation_time = 0.0);
        let (workspace, mut app) = root_list_test_app(&ctx, two_results());
        app.test_skip_history_persistence = true;
        prepare_settings_cross_owner_root(&ctx, &mut app);

        // Keep a deliberately unsaved Main Settings draft while the local
        // editor is taken for the root render and restored around the
        // dedicated Theme window.
        app.settings_editor.toast_duration = 9.25;
        let main_settings_draft = app.settings_editor.toast_duration;
        let committed_settings = persist_cross_owner_test_settings(&app.settings_path);

        open_settings_cross_owner_destination(
            &ctx,
            &mut app,
            "typography scale",
            "theme.typography_scale",
        );
        let (query_id, _) = app
            .settings_editor
            .test_search_query_response
            .expect("the real Settings search query response is rendered");
        assert!(
            app.settings_editor
                .test_search_result_responses
                .iter()
                .any(|(id, _, _)| id == "theme.typography_scale")
        );
        ctx.memory_mut(|memory| memory.request_focus(query_id));
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(query_id));

        assert!(app.is_theme_settings_dialog_open());
        assert!(
            app.settings_editor
                .pending_settings_navigation
                .as_ref()
                .is_some_and(|pending| {
                    pending.control_id == "theme.typography_scale"
                        && pending.section
                            == crate::settings_editor::catalog::SettingsSection::Theme
                }),
            "opening Theme leaves a typed request for its real dedicated response; history={:?}",
            app.settings_editor.test_search_navigation_history
        );
        let dedicated_navigation_budget = app
            .settings_editor
            .pending_settings_navigation
            .as_ref()
            .expect("the destination request remains pending before its owner renders")
            .frames_remaining as usize;

        let mut actual_response = None;
        let mut saw_open_before_owner_eligibility = false;
        let mut saw_noninteractive_sizing_pass =
            app.theme_settings_dialog.saw_noninteractive_window_pass;
        for _ in 0..dedicated_navigation_budget {
            run_settings_cross_owner_frame(&ctx, &mut app, Vec::new());
            saw_noninteractive_sizing_pass |=
                app.theme_settings_dialog.saw_noninteractive_window_pass;
            saw_open_before_owner_eligibility |= app
                .settings_editor
                .test_search_navigation_history
                .iter()
                .any(|event| {
                    event.starts_with(
                        "dedicated owner waiting control=theme.typography_scale eligible=false",
                    )
                });
            if let Some((control_id, response_id)) = app
                .settings_editor
                .test_last_dedicated_navigation_focus
                .as_ref()
                && control_id == "theme.typography_scale"
                && ctx.memory(|memory| memory.focused()) == Some(*response_id)
            {
                actual_response = Some(*response_id);
                break;
            }
        }
        assert!(
            saw_open_before_owner_eligibility,
            "the root lifecycle observed the destination open during its sizing pass before native-owner eligibility; history={:?}",
            app.settings_editor.test_search_navigation_history
        );
        assert!(
            saw_noninteractive_sizing_pass,
            "the actual Theme Window reported a noninteractive egui sizing/visibility pass; window_pass={:?}, scroll={:?}",
            app.theme_settings_dialog.last_window_pass_state,
            app.theme_settings_dialog.test_scroll_area_history
        );
        let actual_response = actual_response.unwrap_or_else(|| {
            panic!(
                "the real Theme typography Slider response eventually owns focus after sizing; history={:?}, scroll={:?}",
                app.settings_editor.test_search_navigation_history,
                app.theme_settings_dialog.test_scroll_area_history,
            )
        });
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(actual_response));
        assert!(app.settings_editor.pending_settings_navigation.is_none());
        assert!(
            app.settings_editor
                .settings_navigation_highlight
                .as_ref()
                .is_some_and(|highlight| {
                    highlight.control_id == "theme.typography_scale"
                        && highlight.section
                            == crate::settings_editor::catalog::SettingsSection::Theme
                })
        );
        assert_eq!(app.settings_editor.toast_duration, main_settings_draft);
        assert_eq!(
            std::fs::read(&app.settings_path).unwrap(),
            committed_settings
        );

        let highlight_history_start = app.settings_editor.test_search_navigation_history.len();
        run_settings_cross_owner_frame(&ctx, &mut app, Vec::new());
        assert_eq!(
            app.settings_editor
                .test_last_navigation_highlight
                .as_ref()
                .map(|(control_id, response_id)| (control_id.as_str(), *response_id)),
            Some(("theme.typography_scale", actual_response)),
            "a steady dedicated-owner frame observes the exact current Theme response"
        );
        assert_eq!(ctx.memory(|memory| memory.focused()), Some(actual_response));
        assert!(
            app.settings_editor.test_search_navigation_history[highlight_history_start..]
                .iter()
                .any(|event| {
                    event.contains("control=theme.typography_scale")
                        && event.contains("focus_requested=false")
                }),
            "the highlight observer does not send another focus directive"
        );

        let original_typography_scale =
            app.theme_settings_dialog.draft.preferences.typography_scale;
        run_settings_cross_owner_frame(
            &ctx,
            &mut app,
            vec![key_press(egui::Key::ArrowRight, egui::Modifiers::NONE)],
        );
        assert!(
            app.theme_settings_dialog.draft.preferences.typography_scale
                > original_typography_scale,
            "a deliberate arrow after actual response focus edits only the Theme draft"
        );
        run_settings_cross_owner_frame(
            &ctx,
            &mut app,
            vec![key_release(egui::Key::ArrowRight, egui::Modifiers::NONE)],
        );
        app.close_theme_settings_dialog();
        assert!(!app.is_theme_settings_dialog_open());
        assert!(app.settings_editor.settings_navigation_highlight.is_none());
        assert_eq!(app.settings_editor.toast_duration, main_settings_draft);
        assert_eq!(
            std::fs::read(&app.settings_path).unwrap(),
            committed_settings
        );
        drop(workspace);
    }

    #[test]
    fn settings_search_cross_owner_gesture_interval_focuses_with_jump_on_and_off() {
        for jump_enabled in [false, true] {
            let ctx = egui::Context::default();
            ctx.global_style_mut(|style| style.animation_time = 0.0);
            let (workspace, mut app) = root_list_test_app(&ctx, two_results());
            app.plugins.register_builtin_for_settings_test(
                crate::plugins::mouse_gestures::MouseGesturesPlugin::default(),
            );
            let mut enabled_plugins = app.enabled_plugins.clone().unwrap_or_default();
            enabled_plugins.insert("mouse_gestures".to_owned());
            app.enabled_plugins = Some(enabled_plugins);
            app.plugins
                .sync_enabled_plugins(app.enabled_plugins.as_ref());
            assert!(
                app.plugins
                    .settings_catalog_snapshot_if_changed(None)
                    .is_some_and(|snapshot| {
                        snapshot.plugins.iter().any(|plugin| {
                            plugin.name == "mouse_gestures" && plugin.has_settings && plugin.enabled
                        })
                    })
            );
            app.test_skip_history_persistence = true;
            app.set_jump_mode_enabled(jump_enabled);
            prepare_settings_cross_owner_root(&ctx, &mut app);
            let committed_settings = persist_cross_owner_test_settings(&app.settings_path);

            open_settings_cross_owner_destination(
                &ctx,
                &mut app,
                "gesture trail refresh interval",
                "mouse_gestures.trail_interval",
            );
            assert!(app.is_mouse_gesture_settings_dialog_open());
            let actual_response = wait_for_settings_cross_owner_focus(
                &ctx,
                &mut app,
                "mouse_gestures.trail_interval",
            )
            .unwrap_or_else(|| {
                panic!(
                    "the real Gesture interval response receives focus with Jump {jump_enabled}; history={:?}",
                    app.settings_editor.test_search_navigation_history
                )
            });
            assert_eq!(ctx.memory(|memory| memory.focused()), Some(actual_response));
            assert_eq!(
                app.mouse_gesture_settings_dialog
                    .test_settings()
                    .trail_interval_ms,
                crate::plugins::mouse_gestures::MouseGestureSettings::default().trail_interval_ms
            );
            assert!(!app.mouse_gesture_settings_dialog.test_dirty());
            assert!(app.settings_editor.pending_settings_navigation.is_none());
            assert_eq!(
                std::fs::read(&app.settings_path).unwrap(),
                committed_settings
            );
            drop(workspace);
        }
    }

